function sortKeysDeep(obj) {
    if (Array.isArray(obj)) {
        return obj.map(sortKeysDeep);
    } else if (obj && typeof obj === "object") {
        return Object.keys(obj)
            .sort()
            .reduce((result, key) => {
                result[key] = sortKeysDeep(obj[key]);
                return result;
            }, {});
    }
    return obj;
}

