    (thread1, thread2) => {
        const aLastInterestDt = thread1.lastInterestDt;
        const bLastInterestDt = thread2.lastInterestDt;
        if (aLastInterestDt && bLastInterestDt) {
            const res = compareDatetime(bLastInterestDt, aLastInterestDt);
            if (res !== 0) {
                return res;
            }
        }
    },
    { sequence: 30 }
