registerTemplate("web.SwitchCompanyMenu.Items", `/web/static/src/webclient/switch_company_menu/switch_company_menu.xml`, `<t t-name="web.SwitchCompanyMenu.Items" xml:space="preserve">
    <div class="d-flex flex-row pe-2 mb-2" t-att-class="{ 'visually-hidden': !state.showFilter }">
        <div role="menuitemcheckbox" t-att-aria-checked="hasSelectedCompanies ? 'true' : 'false'" t-att-aria-label="hasSelectedCompanies ? 'Deselect all' : 'Select all'" t-att-title="hasSelectedCompanies ? 'Deselect all' : 'Select all'" t-on-click="() =&gt; this.selectAll()">
            <span class="btn border-0 pt-2 px-2" t-att-class="selectAllClass">
                <i class="fa fa-fw" t-att-class="selectAllIcon"/>
            </span>
        </div>
        <div class="form-control d-flex align-items-center py-1" role="search">
            <i class="oi oi-search me-2" role="img" aria-label="Search..." title="Search..."/>
            <div class="d-flex flex-grow-1 flex-wrap gap-1">
                <input t-on-input="this.onSearch" t-att-value="this.state.searchFilter" t-ref="inputRef" type="text" class="o_input flex-grow-1 border-0 o-navigable" placeholder="Search..." role="searchbox"/>
            </div>
        </div>
    </div>

    <div class="o_switch_company_menu_items">
        <t t-foreach="visibleCompanies" t-as="entry" t-key="entry.company.id">
            <SwitchCompanyItem company="entry.company" level="entry.level"/>
        </t>
    </div>

    <div t-if="companySelector.hasSelectionChanged" class="o_switch_company_menu_buttons d-flex justify-content-end gap-2 px-2 pt-2">
        <button class="btn btn-primary o-navigable flex-grow-1 text-center" t-on-click="() =&gt; this.confirm()">
            Confirm
        </button>
        <button class="btn btn-secondary o-navigable flex-grow-1 text-center" t-on-click="() =&gt; companySelector.reset()">
            Reset
        </button>
    </div>
</t>

`);
registerTemplate("web.UserMenu", `/web/static/src/webclient/user_menu/user_menu.xml`, `<t t-name="web.UserMenu" xml:space="preserve">
        <div class="o_user_menu d-none d-md-block pe-0 bg-inherit">
            <DropdownGroup group="'web-navbar-group'">
                <Dropdown>
                    <button class="py-1 py-lg-0">
                        <img class="o_avatar o_user_avatar rounded" t-att-src="source" alt="User"/>
                        <small class="oe_topbar_name d-none ms-2 text-start smaller lh-1 text-truncate" t-att-class="{'d-lg-inline-block' : env.debug}" style="max-width: 200px">
                            <t t-esc="userName"/>
                            <mark class="d-block font-monospace text-truncate">
                                <i class="fa fa-database oi-small me-1"/><t t-esc="dbName"/>
                            </mark>
                        </small>
                    </button>
                    <t t-set-slot="content">
                        <t t-foreach="getElements()" t-as="element" t-key="element_index">
                            <t t-if="!element.hide">
                                <t t-if="element.type === 'component'" t-component="element.contentComponent"/>
                                <DropdownItem t-if="element.type == 'item' || element.type == 'switch'" attrs="{ href: element.href, 'data-menu': element.id }" onSelected="element.callback">
                                <div class="d-flex justify-content-between p-0 w-100">
                                    <t t-out="element.description"/>
                                    <CheckBox t-if="element.type == 'switch'" value="element.isChecked" className="'form-switch ms-2'" onChange="element.callback">
                                    </CheckBox>
                                </div>
                                </DropdownItem>
                                <div t-if="element.type == 'separator'" role="separator" class="dropdown-divider"/>
                            </t>
                        </t>
                    </t>
                </Dropdown>
            </DropdownGroup>
        </div>
    </t>

`);
