registerTemplate("account.AccountPaymentField", `/account/static/src/components/account_payment_field/account_payment.xml`, `<t t-name="account.AccountPaymentField" xml:space="preserve">
        <div>
            <t t-set="info" t-value="this.getInfo()"/>
            <t t-if="info.outstanding">
                <div>
                    <strong class="float-start" id="outstanding" t-out="info.title"/>
                </div>
            </t>
            <table style="width:100%;">
                <t t-foreach="info.lines" t-as="line" t-key="line_index">
                    <tr>
                    <t t-if="info.outstanding">
                        <td>
                            <a title="assign to invoice" role="button" class="oe_form_field btn btn-secondary outstanding_credit_assign d-print-none" t-att-data-id="line.id" style="margin-right: 0px; padding-left: 5px; padding-right: 5px;" href="#" data-bs-toggle="tooltip" t-on-click.prevent="() =&gt; this.assignOutstandingCredit(info.moveId, line.id)">Add</a>
                        </td>
                        <td style="max-width: 11em;">
                            <a t-att-title="(line.bank_label ? line.bank_label + ' - ' : '') + line.formattedDate" role="button" class="oe_form_field btn btn-link open_account_move" t-on-click="() =&gt; this.openMove(line.move_id)" style="margin-right: 5px; text-overflow: ellipsis; overflow: hidden; white-space: nowrap; padding-left: 0px; width:100%; text-align:left;" data-bs-toggle="tooltip" t-att-payment-id="account_payment_id" t-out="line.journal_name"/>
                        </td>
                    </t>
                    <t t-if="!info.outstanding">
                        <td>
                           <a role="button" tabindex="0" class="js_payment_info fa fa-info-circle" t-att-index="line_index" style="margin-right:5px;" aria-label="Info" title="Journal Entry Info" data-bs-toggle="tooltip" t-on-click.stop="(ev) =&gt; this.onInfoClick(ev, line)"/>
                        </td>
                        <td t-if="!line.is_exchange">
                            <i class="o_field_widget text-start o_payment_label">
                                <t t-if="line.is_refund">Reversed on </t>
                                <t t-else="">Paid on </t>
                                <t t-out="line.formattedDate"/>
                            </i>
                        </td>
                        <td t-if="line.is_exchange" colspan="2">
                            <i class="o_field_widget text-start text-muted text-start">
                                <span class="oe_form_field oe_form_field_float oe_form_field_monetary fw-bold">
                                    <t t-out="line.amount_formatted"/>
                                </span>
                                <span> Exchange Difference</span>
                            </i>
                        </td>
                    </t>
                    <td t-if="!line.is_exchange" style="text-align:right;">
                        <span class="oe_form_field oe_form_field_float oe_form_field_monetary" style="margin-left: -10px;">
                            <t t-out="line.amount_formatted"/>
                        </span>
                    </td>
                    </tr>
                </t>
            </table>
        </div>
    </t>

    `);
