registerTemplate("account.ProductLabelSectionAndNoteField", `/account/static/src/components/product_label_section_and_note_field/product_label_section_and_note_field.xml`, `<t t-name="account.ProductLabelSectionAndNoteField" xml:space="preserve">
        <div class="o_field_product_label_section_and_note_cell">
            <t t-if="isNote()">
                <textarea class="o_input d-print-none border-0 fst-italic" placeholder="Enter a description" rows="1" t-att-class="sectionAndNoteClasses" t-att-readonly="sectionAndNoteIsReadonly" t-att-value="label" t-ref="labelNodeRef" t-key="props.readonly"/>
            </t>
            <t t-elif="isSectionOrSubSection">
                <input type="text" class="o_input text-wrap border-0 w-100" placeholder="Enter a description" t-att-class="sectionAndNoteClasses" t-att-readonly="sectionAndNoteIsReadonly" t-att-value="label" t-ref="labelNodeRef" t-key="props.readonly"/>
            </t>
            <t t-else="">
                <div class="d-flex align-items-center gap-1">
                    <Many2One t-props="this.m2oProps" cssClass="'w-100'" t-on-keydown="onM2oInputKeydown"/>
                    <t t-if="showLabelVisibilityToggler">
                        <button class="btn fa fa-bars text-start o_external_button px-1" type="button" id="labelVisibilityButtonId" data-tooltip="Click or press enter to add a description" t-on-click="() =&gt; this.switchLabelVisibility()"/>
                    </t>
                </div>
                <div t-if="props.readonly" class="o_input d-print-none border-0 fst-italic" t-att-class="{ ...sectionAndNoteClasses, 'd-none': !(columnIsProductAndLabel.value and label) }" t-out="label"/>
                <textarea t-else="" class="o_input d-print-none border-0 fst-italic" placeholder="Enter a description" rows="1" type="text" t-att-class="{ ...sectionAndNoteClasses, 'd-none': !(columnIsProductAndLabel.value and (label or labelVisibility.value)) }" t-att-value="label" t-ref="labelNodeRef"/>
            </t>
            <t t-if="isPrintMode.value">
                <div class="d-none d-print-block text-wrap" t-out="label"/>
            </t>
        </div>
    </t>

`);
