registerTemplate("sale.ComboConfiguratorDialog", `/sale/static/src/js/combo_configurator_dialog/combo_configurator_dialog.xml`, `<t t-name="sale.ComboConfiguratorDialog" xml:space="preserve">
        <Dialog title="props.display_name" contentClass="'sale-combo-configurator-dialog'" bodyClass="'d-flex flex-column gap-4'">
            <div t-if="unconfigurableCombos.length" class="mb-4">
                <span class="d-inline-block mb-3 h4">
                    Included
                </span>
                <div class="container">
                    <div t-foreach="unconfigurableCombos" t-as="combo" t-key="combo.id" class="row mb-3">
                        <t t-set="product" t-value="combo.combo_items[0].product"/>
                        <div class="col-2 p-0">
                            <img t-attf-src="/web/image/product.product/{{product.id}}/image_256" alt="Product Image" role="img" class="img-thumbnail rounded"/>
                        </div>
                        <div name="preselected_product_name" class="col d-flex justify-content-center text-break flex-column">
                            <span name="preselected_product_title" t-out="product.display_name" class="h5"/>
                            <div t-if="product.description" t-out="product.description" class="text-muted small text-truncate"/>
                        </div>
                    </div>
                </div>
            </div>
            <div t-foreach="configurableCombos" t-as="combo" t-key="combo.id">
                <span name="sale_combo_configurator_title" t-attf-class="d-inline-block mb-3 h4 {{combo_index !== 0? 'mt-4' : ''}}" t-out="combo.name"/>
                <div class="row row-cols-1 row-cols-md-3 g-3">
                    <t t-foreach="combo.combo_items" t-as="comboItem" t-key="comboItem.id">
                        <ProductCard product="getSelectedOrProvidedComboItem(combo.id, comboItem).product" extraPrice="comboItem.extra_price" onClick="() =&gt; this.selectComboItem(combo.id, comboItem)" isSelected="state.selectedComboItems.get(combo.id)?.id === comboItem.id" isConfigurable="comboItem.is_configurable"/>
                    </t>
                </div>
            </div>
            <t t-set-slot="footer">
                <div class="d-flex flex-column-reverse flex-lg-row gap-3 w-100">
                    <div class="d-flex flex-column flex-md-row gap-2">
                        <button name="sale_combo_configurator_confirm_button" class="btn btn-primary w-100 w-lg-auto" t-att-disabled="!areAllCombosSelected || state.isLoading" t-on-click="confirm">
                            Add to order
                        </button>
                        <button name="sale_combo_configurator_cancel_button" class="btn btn-secondary w-100 w-lg-auto" t-on-click="cancel">
                            Cancel
                        </button>
                    </div>
                    <div class="d-flex gap-3 align-items-center">
                        <div t-if="props.options?.showQuantity ?? true" class="combo_configurator_quantity ps-lg-3">
                            <QuantityButtons quantity="state.quantity" setQuantity="quantity =&gt; this.setQuantity(quantity)" isMinusButtonDisabled="state.quantity === 1" btnClasses="'d-inline-block w-auto'"/>
                        </div>
                        <div t-if="props.options?.showPrice ?? true" class="w-100 w-md-auto">
                            <span name="sale_combo_configurator_total" class="h6 mb-0" t-out="totalMessage"/>
                            <span t-if="this.props.price_info" t-out="this.props.price_info" class="text-muted"/>
                        </div>
                    </div>
                </div>
            </t>
        </Dialog>
    </t>
`);
registerTemplate("sale.Product", `/sale/static/src/js/product/product.xml`, `<t t-name="sale.Product" xml:space="preserve">
        <td class="o_sale_product_configurator_img py-3 px-0">
            <img class="w-75 w-lg-100 border rounded" t-att-src="imageUrl" alt="Product Image"/>
        </td>
        <td class="p-0 p-md-3 product_name_description">
            <div name="o_sale_product_configurator_name" class="mb-1 mb-lg-3 text-break text-truncate">
                <span class="h5" t-out="this.props.display_name"/>
                <div t-if="this.props.description_sale" t-out="this.props.description_sale" class="text-muted small text-truncate"/>
                <div t-if="this.props.selectedComboItems" class="text-muted small">
                    <div t-foreach="this.props.selectedComboItems" t-as="comboItem" t-key="comboItem_index" t-out="comboItem.name"/>
                </div>
            </div>
            <t t-foreach="this.props.attribute_lines" t-as="ptal" t-key="ptal.id">
                <PTAL t-if="shouldShowPtal(ptal)" t-props="ptal" productTmplId="this.props.product_tmpl_id"/>
            </t>
            <div t-if="!this.env.isPossibleCombination(this.props)" class="alert alert-warning impossible_combination_alert mt-3">
                <span>This option or combination of options is not available</span>
            </div>
            <t t-if="this.props.available_uoms" t-call="sale.uom_selector"/>
        </td>
        <t t-if="!this.props.optional">
            <td class="o_sale_product_configurator_qty w-25 py-3 px-0 text-end">
                <div t-if="env.showPrice" class="d-md-flex gap-2 align-items-baseline justify-content-end">
                    <t t-call="sale.product_price" name="sale_product_configurator_price"/>
                </div>
                <t t-set="isComboProduct" t-value="isMainProduct &amp;&amp; this.props.selectedComboItems.length"/>
                <t t-if="env.showQuantity &amp;&amp; !isComboProduct">
                    <QuantityButtons quantity="this.props.quantity" setQuantity="quantity =&gt; this.env.setQuantity(this.props.product_tmpl_id, quantity)" isMinusButtonDisabled="this.props.quantity === 1 &amp;&amp; isMainProduct"/>
                </t>
                <span t-elif="env.showQuantity &amp;&amp; isComboProduct" t-out="this.props.quantity" class="h5"/>
                <a class="d-block mt-2 text-end" role="button" t-if="!isMainProduct" t-on-click="() =&gt; this.env.removeProduct(this.props.product_tmpl_id)">
                    Remove
                </a>
            </td>
        </t>
        <t t-else="">
            <td name="price" class="o_sale_product_configurator_price py-3 px-0 text-end">
                <div t-if="env.showPrice" class="d-md-flex gap-2 align-items-baseline justify-content-end">
                    <t t-call="sale.product_price" name="sale_product_configurator_optional_price"/>
                </div>
                <button name="sale_product_configurator_add_button" class="btn btn-secondary" t-att-class="{'disabled': !this.env.isPossibleCombination(this.props)}" t-on-click="() =&gt; this.env.addProduct(this.props.product_tmpl_id)">
                    <i class="oi oi-plus" role="img"/>
                    <span name="add_button" class="ms-2 d-none d-md-inline">Add</span>
                </button>
            </td>
        </t>
    </t>

    `);
