registerTemplate("mass_mailing.MassMailingIframe", `/mass_mailing/static/src/iframe/mass_mailing_iframe.xml`, `<t t-name="mass_mailing.MassMailingIframe" xml:space="preserve">
        <div class="o_mass_mailing_iframe_wrapper" t-att-class="{                 'o_mass_mailing_fullscreen': state.showFullscreen,                 [props.extraClass]: props.extraClass,             }">
            <div class="d-flex w-100 h-100">
                <div class="flex-grow-1" t-att-class="{'align-self-center': this.state.isMobile}">
                    <LocalOverlayContainer localOverlay="overlayRef" identifier="env.localOverlayContainerKey"/>
                    <div t-att-class="{ 'o_is_mobile': this.state.isMobile, 'h-100': !this.state.isMobile }">
                        <iframe t-att-sandbox="this.isBrowserSafari ? 'allow-same-origin allow-scripts' : 'allow-same-origin'" t-att-scrolling="this.state.isMobile ? '' : 'no'" t-att-class="{ 'd-none': props.showThemeSelector or props.showCodeView }" t-ref="iframeRef" t-on-blur="onBlur"/>
                    </div>
                </div>
                <div t-if="!props.readonly and props.withBuilder and !props.showThemeSelector and !props.showCodeView">
                    <div class="position-sticky o_mass_mailing-builder_sidebar border-start border-dark o_builder_sidebar_open" t-att-class="{ 'd-none': this.env.isSmall }" t-ref="sidebarRef">
                        <LazyComponent t-if="state.ready" Component="'mass_mailing.MassMailingBuilder'" props="() =&gt; ({                                 builderProps: this.getBuilderProps(),                                 toggleCodeView: this.props.toggleCodeView,                                 toggleFullScreen: () =&gt; this.toggleFullScreen(),                             })" bundle="'mass_mailing.assets_builder'"/>
                    </div>
                </div>
            </div>
        </div>
    </t>
    `);
registerTemplate("mass_mailing.IframeHead", `/mass_mailing/static/src/iframe/mass_mailing_iframe.xml`, `<t t-name="mass_mailing.IframeHead" xml:space="preserve">
        <meta http-equiv="Content-Security-Policy" content="script-src 'none';"/>
        <meta charset="utf-8"/>
        <meta http-equiv="X-UA-Compatible" content="IE=edge"/>
        <meta name="viewport" content="width=device-width, initial-scale=1, user-scalable=no"/>
    </t>
    `);
registerTemplate("mass_mailing.IframeBody", `/mass_mailing/static/src/iframe/mass_mailing_iframe.xml`, `<t t-name="mass_mailing.IframeBody" xml:space="preserve">
        <div class="o_mass_mailing_value" t-att-class="{ 'o_readonly': props.readonly, 'note-editable': !props.readonly, 'o_rtl': isRTL }">
            <t t-if="props.readonly">
                <t t-out="props.config.value"/>
            </t>
        </div>
        <div class="o_mass_mailing_processing_container" style="             position: absolute;             top: -9999px;             left: -9999px;             visibility: hidden;             pointer-events: none;             min-width: 100%;             " aria-hidden="true"/>
        </t>
`);
registerTemplate("mass_mailing.MailingFilter", `/mass_mailing/static/src/xml/mailing_filter_widget.xml`, `<t t-name="mass_mailing.MailingFilter" xml:space="preserve">
        <div class="d-flex align-items-center gap-1">
            <Many2One t-props="m2oProps" cssClass="'w-100'"/>
            <t t-if="!props.readonly">
                <div class="o_mass_mailing_filter_container">
                    <div t-attf-class="o_mass_mailing_save_filter_container pt-1 {{ !this.filter.canSaveFilter ? 'd-none': '' }}">
                        <div class="o_mass_mailing_filter_dropdown">
                            <MailingFilterDropdown>
                                <button class="btn py-0">
                                    <span class="o_mass_mailing_add_filter">
                                        <span t-attf-class="o_mass_mailing_no_filter {{ this.props.record.data.mailing_filter_count ? 'd-none' : '' }}">Save as Favorite Filter</span>
                                        <i class="fa fa-floppy-o px-1 py-1"/>
                                    </span>
                                </button>
                                <t t-set-slot="content">
                                    <div class="ms-2 fw-light">
                                        Add to favorite filters
                                    </div>
                                    <div class="d-inline-flex">
                                        <input t-ref="autofocus" type="text" class="o_mass_mailing_filter_name o_input w-auto ms-2" placeholder="e.g. &quot;VIP Customers&quot;" t-on-keydown="onFilterNameInputKeydown"/>
                                        <button class="btn btn-sm btn-primary o_mass_mailing_btn_save_filter mx-2" t-on-click="onSaveFilter">
                                            Add
                                        </button>
                                    </div>
                                </t>
                            </MailingFilterDropdown>
                        </div>
                    </div>
                    <a t-attf-class="o_mass_mailing_remove_filter btn px-1 pt-1 pb-0 {{ !this.filter.canRemoveFilter ? 'd-none': '' }}" t-on-click="onRemoveFilter">
                        <i class="fa fa-trash px-3 py-1 align-bottom" title="Remove from Favorites"/>
                    </a>
                </div>
            </t>
        </div>
    </t>

`);
registerTemplate("tcrm_ai.TcrmAiChat", `/tcrm_ai/static/src/tcrm_ai_chat/tcrm_ai_chat.xml`, `<t t-name="tcrm_ai.TcrmAiChat" xml:space="preserve">
        <div class="o_tcrm_ai_chat d-flex flex-column h-100 p-4">
            <div class="mb-3">
                <h4 class="mb-0">TCRM AI</h4>
                <p class="text-muted small mb-0">Ask about payment plans, sales, clients, or anything. Answers use this database and can include links to records.</p>
            </div>
            <div class="flex-grow-1 overflow-auto mb-3 border rounded p-3 bg-light" style="min-height: 200px;">
                <t t-if="state.history.length === 0">
                    <p class="text-muted">No messages yet. Type a question below.</p>
                </t>
                <t t-else="">
                    <t t-foreach="state.history" t-as="item" t-key="item_index">
                        <div t-attf-class="mb-3 #{item.role === 'user' ? 'text-end' : ''}">
                            <t t-if="item.role === 'user'">
                                <span class="badge bg-primary p-2"><t t-esc="item.content"/></span>
                            </t>
                            <t t-else="">
                                <div class="text-start">
                                    <div t-if="item.error" class="text-danger small"><t t-esc="item.answer"/></div>
                                    <div t-else="" class="small">
                                        <div class="d-flex flex-wrap gap-1 mb-1">
                                            <button type="button" class="btn btn-outline-secondary btn-sm" t-on-click="() =&gt; this.onCopy(item)">Copy</button>
                                            <t t-if="item.tables and item.tables.length">
                                                <button type="button" class="btn btn-outline-secondary btn-sm" t-on-click="() =&gt; this.onExport(item, 'xlsx')">Export Excel</button>
                                                <button type="button" class="btn btn-outline-secondary btn-sm" t-on-click="() =&gt; this.onExport(item, 'html')">Preview HTML</button>
                                                <button type="button" class="btn btn-outline-secondary btn-sm" t-on-click="() =&gt; this.onExport(item, 'pdf')">Export PDF</button>
                                            </t>
                                        </div>
                                        <div class="o_tcrm_ai_answer text-break" style="white-space: pre-wrap;" t-esc="item.answer"/>
                                        <t t-if="item.tables and item.tables.length">
                                            <t t-foreach="item.tables" t-as="tbl" t-key="tbl_index">
                                                <div class="table-responsive mt-2">
                                                    <table class="table table-sm table-bordered">
                                                        <thead><tr>
                                                            <t t-foreach="tbl.headers" t-as="h" t-key="h"><th t-esc="h"/></t>
                                                        </tr></thead>
                                                        <tbody>
                                                            <t t-foreach="tbl.rows" t-as="row" t-key="row_index">
                                                                <tr><t t-foreach="row" t-as="cell" t-key="cell_index"><td t-esc="cell"/></t></tr>
                                                            </t>
                                                        </tbody>
                                                    </table>
                                                </div>
                                            </t>
                                        </t>
                                        <t t-if="item.links and item.links.length">
                                            <div class="mt-2">
                                                <t t-foreach="item.links" t-as="link" t-key="link_index">
                                                    <a t-att-href="link.url" t-esc="link.label" class="btn btn-link btn-sm p-0 me-2"/>
                                                </t>
                                            </div>
                                        </t>
                                    </div>
                                </div>
                            </t>
                        </div>
                    </t>
                </t>
            </div>
            <div class="d-flex gap-2">
                <input type="text" class="form-control" t-att-placeholder="placeholder" t-model="state.message" t-on-keydown="onKeydown" placeholder="Ask anything…"/>
                <button type="button" class="btn btn-primary" t-on-click="onSend" t-att-disabled="state.loading">
                    <t t-if="state.loading">...</t>
                    <t t-else="">Send</t>
                </button>
            </div>
        </div>
    </t>
`);
registerTemplate("tcrm_propertio.PropertioDashboard", `/tcrm_propertio/static/src/dashboard/propertio_dashboard.xml`, `<t t-name="tcrm_propertio.PropertioDashboard" xml:space="preserve">
        <div class="o_propertio_dashboard p-4">
            <t t-if="state.loading and !state.data">
                <div class="text-center py-5 text-muted">Loading dashboard…</div>
            </t>
            <t t-elif="state.error">
                <div class="alert alert-danger"><t t-esc="state.error"/></div>
            </t>
            <t t-else="">
                <t t-if="state.data">
                    <div class="o_propertio_dashboard_toolbar card border-0 shadow-sm mb-4 p-3">
                        <div class="row g-2 align-items-end flex-wrap">

                            <div class="col-12 col-xl-auto">
                                <span class="small text-muted d-block mb-1">Period</span>
                                <div class="d-flex flex-wrap gap-3 align-items-start o_propertio_dashboard_calendar_picker">
                                    <div class="o_calendar_sidebar">
                                        <span class="small text-muted d-block mb-1">From</span>
                                        <DateTimePicker t-props="dateFromPickerProps"/>
                                    </div>
                                    <div class="o_calendar_sidebar">
                                        <span class="small text-muted d-block mb-1">To</span>
                                        <DateTimePicker t-props="dateToPickerProps"/>
                                    </div>
                                </div>
                            </div>
                            <div class="col-auto d-flex flex-wrap gap-2 align-items-center">
                                <button type="button" class="btn btn-primary btn-sm" t-on-click="applyPeriodFilter">Apply</button>
                                <button type="button" class="btn btn-outline-secondary btn-sm" t-on-click="resetPeriodFilter">Reset</button>
                            </div>
                            <div class="col-12 col-lg-auto ms-lg-auto">
                                <span class="small text-muted d-block mb-1">Presets</span>
                                <div class="btn-group btn-group-sm flex-wrap" role="group">
                                    <button type="button" class="btn btn-outline-secondary" t-on-click="setPeriodThisMonth">This month</button>
                                    <button type="button" class="btn btn-outline-secondary" t-on-click="setPeriodLastMonth">Last month</button>
                                    <button type="button" class="btn btn-outline-secondary" t-on-click="setThisYearToDate">YTD</button>
                                </div>
                            </div>
                            <div class="col-12 col-lg-auto d-flex align-items-end">
                                <button type="button" class="btn btn-link btn-sm text-decoration-none px-0" t-on-click="openReportsCenter">Reports Center ?</button>
                            </div>
                        </div>
                        <p class="small text-muted mb-0 mt-2" t-if="state.data.period_label">
                            Active period: <strong t-esc="state.data.period_label"/></p>
                    </div>
                    <div class="mb-4">
                        <h4 class="o_propertio_dashboard_title">
                            <t t-if="state.data.role === 'sales'">Good morning, <t t-esc="state.data.user_name"/>!</t>
                            <t t-elif="state.data.role === 'collection'">Collection Dashboard</t>
                            <t t-elif="state.data.role === 'finance'">Finance Dashboard</t>
                            <t t-elif="state.data.role === 'manager' or state.data.role === 'admin'">Company Overview</t>
                            <t t-else="">Dashboard</t>
                        </h4>
                        <p class="text-muted small mb-0">Today: <t t-esc="state.data.date"/></p>
                    </div>


                    <t t-if="state.data.role === 'sales'">
                        <div class="row g-3 mb-4">
                            <div class="col-6 col-md-3">
                                <div class="card border-0 shadow-sm propertio-kpi-card">
                                    <div class="card-body">
                                        <div class="small text-muted">My Sales</div>
                                        <div class="h4 mb-0"><t t-esc="state.data.my_sales_count"/></div>
                                    </div>
                                </div>
                            </div>
                            <div class="col-6 col-md-3">
                                <div class="card border-0 shadow-sm propertio-kpi-card">
                                    <div class="card-body">
                                        <div class="small text-muted">Sales in period</div>
                                        <div class="h4 mb-0"><t t-esc="state.data.this_month_count"/></div>
                                    </div>
                                </div>
                            </div>
                            <div class="col-6 col-md-3">
                                <div class="card border-0 shadow-sm propertio-kpi-card">
                                    <div class="card-body">
                                        <div class="small text-muted">Target</div>
                                        <div class="h4 mb-0"><t t-esc="state.data.target_units"/> units</div>
                                    </div>
                                </div>
                            </div>
                            <div class="col-6 col-md-3">
                                <div class="card border-0 shadow-sm propertio-kpi-card">
                                    <div class="card-body">
                                        <div class="small text-muted">Achieved</div>
                                        <div class="h4 mb-0"><t t-esc="state.data.achieved_pct"/>%</div>
                                        <div class="small">Remaining: <t t-esc="state.data.remaining_days"/> days</div>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div class="row g-3 mb-4">
                            <div class="col-12 col-md-6">
                                <div class="card border-0 shadow-sm">
                                    <div class="card-header bg-transparent">Tasks in period</div>
                                    <div class="card-body">
                                        <t t-if="state.data.today_tasks and state.data.today_tasks.length">
                                            <ul class="list-unstyled mb-0">
                                                <t t-foreach="state.data.today_tasks" t-as="task" t-key="task.id">
                                                    <li class="mb-2">
                                                        <a href="#" t-on-click.prevent="() =&gt; this.openAction(task.res_model, task.res_id)">
                                                            <t t-esc="task.summary or task.note or (task.res_model + ' #' + task.res_id)"/>
                                                        </a>
                                                    </li>
                                                </t>
                                            </ul>
                                        </t>
                                        <t t-else="">
                                            <p class="text-muted mb-0">No tasks due today.</p>
                                        </t>
                                    </div>
                                </div>
                            </div>
                            <div class="col-12 col-md-6">
                                <div class="card border-0 shadow-sm">
                                    <div class="card-header bg-transparent">Quick Actions</div>
                                    <div class="card-body">
                                        <p class="mb-2">Available units: <strong t-esc="state.data.available_units_count"/></p>
                                        <button class="btn btn-primary btn-sm me-2" t-on-click="openNewSale">New Sale</button>
                                        <button class="btn btn-outline-secondary btn-sm" t-on-click="openUnits">Browse Units</button>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <t t-if="state.data.pipeline and state.data.pipeline.length">
                            <div class="card border-0 shadow-sm mb-4">
                                <div class="card-header bg-transparent">Leads pipeline (created in period)</div>
                                <div class="card-body">
                                    <div class="d-flex flex-wrap gap-2">
                                        <t t-foreach="state.data.pipeline" t-as="p" t-key="p.stage">
                                            <span class="badge bg-light text-dark"><t t-esc="p.stage"/>: <t t-esc="p.count"/></span>
                                        </t>
                                    </div>
                                </div>
                            </div>
                        </t>
                    </t>


                    <t t-if="state.data.role === 'collection'">
                        <div class="row g-3 mb-4">
                            <div class="col-12">
                                <div class="d-flex justify-content-between align-items-center mb-3">
                                    <span class="text-danger fw-bold">Red Alerts: <t t-esc="state.data.red_alerts_count"/> customers overdue &gt; 15 days</span>
                                    <button class="btn btn-outline-danger btn-sm" t-on-click="openRedAlerts">View All</button>
                                </div>
                                <div class="text-muted small">Due this week: <t t-esc="state.data.due_this_week_count"/> installments · Total: <t t-esc="formatMoney(state.data.due_this_week_total)"/></div>
                            </div>
                        </div>
                        <div class="card border-0 shadow-sm mb-4">
                            <div class="card-header bg-transparent">Today's Collection Calls</div>
                            <div class="card-body">
                                <t t-if="state.data.today_calls and state.data.today_calls.length">
                                    <ul class="list-unstyled mb-0">
                                        <t t-foreach="state.data.today_calls" t-as="c" t-key="c.id">
                                            <li class="d-flex justify-content-between align-items-center py-2 border-bottom">
                                                <span><t t-esc="c.partner_name"/> · <t t-esc="c.unit_name"/> · <t t-esc="formatMoney(c.amount, c.currency)"/> · <t t-esc="c.overdue_days"/> days overdue</span>
                                                <button class="btn btn-outline-primary btn-sm" t-on-click="() =&gt; this.openPaymentForm(c.partner_id, c.sale_id)">Enter Payment</button>
                                            </li>
                                        </t>
                                    </ul>
                                </t>
                                <t t-else="">
                                    <p class="text-muted mb-0">No overdue installments.</p>
                                </t>
                            </div>
                        </div>
                        <div class="card border-0 shadow-sm mb-4">
                            <div class="card-header bg-transparent">Collection vs target (period)</div>
                            <div class="card-body">
                                <p class="mb-2">Target: <t t-esc="formatMoney(state.data.target_collection)"/> · Collected: <t t-esc="formatMoney(state.data.collected_mtd)"/> (<t t-esc="state.data.collection_pct"/>%)</p>
                                <div class="progress" style="height: 24px;">
                                    <div class="progress-bar" t-att-style="'width: ' + Math.min(100, state.data.collection_pct) + '%;'"/>
                                </div>
                                <p class="small text-muted mt-2 mb-0">Remaining this month: <t t-esc="formatMoney(state.data.remaining_this_month)"/></p>
                            </div>
                        </div>
                        <button class="btn btn-primary" t-on-click="() =&gt; this.openPaymentForm()">Enter Payment</button>
                    </t>


                    <t t-if="state.data.role === 'finance'">
                        <div class="card border-0 shadow-sm mb-4">
                            <div class="card-header bg-transparent">Cash received (period)</div>
                            <div class="card-body">
                                <p class="h5">Total received: <t t-esc="formatMoney(state.data.total_received_mtd)"/></p>
                            </div>
                        </div>
                        <div class="card border-0 shadow-sm mb-4">
                            <div class="card-header bg-transparent">Upcoming (Next 7 days)</div>
                            <div class="card-body">
                                <t t-if="state.data.upcoming_7_days and Object.keys(state.data.upcoming_7_days).length">
                                    <t t-foreach="Object.entries(state.data.upcoming_7_days)" t-as="day" t-key="day[0]">
                                        <p class="mb-1"><t t-esc="day[0]"/>: <t t-esc="day[1].count"/> installments · <t t-esc="formatMoney(day[1].amount)"/></p>
                                    </t>
                                </t>
                                <t t-else="">
                                    <p class="text-muted mb-0">No installments due in the next 7 days.</p>
                                </t>
                            </div>
                        </div>
                        <button class="btn btn-primary" t-on-click="openPayments">View Payments</button>
                    </t>


                    <t t-if="state.data.role === 'manager' or state.data.role === 'admin'">
                        <div class="row g-3 mb-4">
                            <div class="col-6 col-md-3">
                                <div class="card border-0 shadow-sm propertio-kpi-card">
                                    <div class="card-body">
                                        <div class="small text-muted">Active Projects</div>
                                        <div class="h4 mb-0"><t t-esc="state.data.projects_count"/></div>
                                    </div>
                                </div>
                            </div>
                            <div class="col-6 col-md-3">
                                <div class="card border-0 shadow-sm propertio-kpi-card">
                                    <div class="card-body">
                                        <div class="small text-muted">Total Units</div>
                                        <div class="h4 mb-0"><t t-esc="state.data.units_total"/></div>
                                    </div>
                                </div>
                            </div>
                            <div class="col-6 col-md-3">
                                <div class="card border-0 shadow-sm propertio-kpi-card">
                                    <div class="card-body">
                                        <div class="small text-muted">Sold</div>
                                        <div class="h4 mb-0"><t t-esc="state.data.units_sold"/> (<t t-esc="state.data.sold_pct"/>%)</div>
                                    </div>
                                </div>
                            </div>
                            <div class="col-6 col-md-3">
                                <div class="card border-0 shadow-sm propertio-kpi-card">
                                    <div class="card-body">
                                        <div class="small text-muted">Sales in period</div>
                                        <div class="h4 mb-0"><t t-esc="state.data.actual_units_this_month"/> / <t t-esc="state.data.target_units"/></div>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div class="row g-3 mb-4">
                            <div class="col-12 col-md-6">
                                <div class="card border-0 shadow-sm">
                                    <div class="card-header bg-transparent">Top Salespersons</div>
                                    <div class="card-body">
                                        <t t-if="state.data.top_salespersons and state.data.top_salespersons.length">
                                            <ol class="mb-0 ps-3">
                                                <t t-foreach="state.data.top_salespersons" t-as="sp" t-key="sp.id">
                                                    <li><t t-esc="sp.name"/> — <t t-esc="sp.count"/> sales · <t t-esc="formatMoney(sp.value)"/></li>
                                                </t>
                                            </ol>
                                        </t>
                                        <t t-else="">
                                            <p class="text-muted mb-0">No sales this month.</p>
                                        </t>
                                    </div>
                                </div>
                            </div>
                            <div class="col-12 col-md-6">
                                <div class="card border-0 shadow-sm">
                                    <div class="card-header bg-transparent">Collection Health</div>
                                    <div class="card-body">
                                        <p class="mb-1">On time: <t t-esc="state.data.on_time_pct"/>%</p>
                                        <p class="mb-1 text-danger">15+ days overdue: <t t-esc="state.data.overdue_15_pct"/>%</p>
                                        <p class="mb-0">Portfolio: GDV <t t-esc="formatMoney(state.data.total_gdv)"/> · Collected <t t-esc="formatMoney(state.data.collected_value)"/></p>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <t t-if="state.data.project_progress and state.data.project_progress.length">
                            <div class="card border-0 shadow-sm mb-4">
                                <div class="card-header bg-transparent">Project Progress</div>
                                <div class="card-body">
                                    <t t-foreach="state.data.project_progress" t-as="proj" t-key="proj.name">
                                        <div class="mb-2">
                                            <span class="me-2"><t t-esc="proj.name"/>:</span>
                                            <div class="progress d-inline-block" style="width: 200px; height: 20px; vertical-align: middle;">
                                                <div class="progress-bar" t-att-style="'width: ' + proj.pct + '%;'" t-att-title="proj.sold + ' / ' + proj.total"/>
                                            </div>
                                            <span class="ms-2"><t t-esc="proj.pct"/>% sold</span>
                                        </div>
                                    </t>
                                </div>
                            </div>
                        </t>
                        <button class="btn btn-primary me-2" t-on-click="openSales">Sales</button>
                        <button class="btn btn-outline-primary" t-on-click="openPayments">Payments</button>
                    </t>


                    <t t-if="state.data.role === 'aftersales'">
                        <div class="card border-0 shadow-sm">
                            <div class="card-body">
                                <p class="mb-0">Tapu appointments this week: <t t-esc="state.data.tapu_appointments_this_week"/></p>
                            </div>
                        </div>
                    </t>
                </t>
            </t>
        </div>
    </t>
`);
registerTemplate("tcrm_propertio.PropertioReportsCenter", `/tcrm_propertio/static/src/reports_center/propertio_reports_center.xml`, `<t t-name="tcrm_propertio.PropertioReportsCenter" xml:space="preserve">
        <div class="o_propertio_reports_center p-4">
            <div class="mb-4">
                <h3 class="mb-1">Propertio <span class="text-muted">·</span> Reports Center</h3>
                <p class="text-muted small mb-0">Open any report in its standard Odoo window (wizard, pivot, graph, or list).</p>
            </div>
            <div class="card border-0 shadow-sm mb-4 p-3">
                <div class="row g-2 align-items-end">
                    <div class="col-12 col-xl-auto">
                        <span class="small text-muted d-block mb-1">Global period</span>
                        <div class="d-flex flex-wrap gap-3 align-items-start">
                            <div class="o_calendar_sidebar">
                                <span class="small text-muted d-block mb-1">From</span>
                                <DateTimePicker t-props="dateFromPickerProps"/>
                            </div>
                            <div class="o_calendar_sidebar">
                                <span class="small text-muted d-block mb-1">To</span>
                                <DateTimePicker t-props="dateToPickerProps"/>
                            </div>
                        </div>
                    </div>
                    <div class="col-auto d-flex flex-wrap gap-2 align-items-center">
                        <button type="button" class="btn btn-outline-secondary btn-sm" t-on-click="resetPeriod">Reset</button>
                    </div>
                </div>
            </div>
            <t t-foreach="sections" t-as="section" t-key="section_index">
                <div class="card border-0 shadow-sm mb-4 o_propertio_report_section">
                    <div class="card-header bg-transparent fw-semibold">
                        <t t-esc="section.title"/>
                    </div>
                    <div class="card-body pt-3">
                        <div class="row g-2">
                            <t t-foreach="section.items" t-as="item" t-key="item.action">
                                <div class="col-12 col-md-6 col-xl-4">
                                    <button type="button" class="btn btn-outline-primary w-100 text-start py-2 o_propertio_report_tile" t-on-click="() =&gt; this.openReport(item.action)">
                                        <t t-esc="item.label"/>
                                    </button>
                                </div>
                            </t>
                        </div>
                    </div>
                </div>
            </t>
        </div>
    </t>
`);
registerTemplate("tcrm_saas_core.CommandCenter", `/tcrm_saas_core/static/src/command_center/command_center.xml`, `<t t-name="tcrm_saas_core.CommandCenter" xml:space="preserve">
<div class="tcrm-cc" t-att-class="{ 'tcrm-cc--sidebar-open': state.sidebarOpen, 'tcrm-cc--light': state.themeLight }">


    <aside class="tcrm-cc-sidebar">
        <div class="tcrm-cc-sidebar__brand">
            <i class="fa-solid fa-shield-halved tcrm-cc-sidebar__logo" title="TCRM"/>
            <div>
                <div class="tcrm-cc-sidebar__title">TCRM</div>
                <div class="tcrm-cc-sidebar__subtitle">COMMAND CENTER</div>
            </div>
        </div>
        <nav class="tcrm-cc-sidebar__nav">
            <t t-foreach="screens" t-as="s" t-key="s.id">
                <button t-att-class="'tcrm-cc-sidebar__item ' + (state.screen === s.id or (state.screen === 'tenant_detail' and s.id === 'tenants') ? 'tcrm-cc-sidebar__item--active' : '')" t-on-click="() =&gt; this.navigateTo(s.id)">
                    <i t-att-class="s.iconClass"/>
                    <span t-esc="s.label"/>
                </button>
            </t>
        </nav>
        <div class="tcrm-cc-sidebar__footer">
            <div class="tcrm-cc-sidebar__status">
                <span class="tcrm-cc-pulse"/> System Operational
            </div>
        </div>
    </aside>
    <div class="tcrm-cc-backdrop" t-att-class="state.sidebarOpen ? 'is-open' : ''" t-on-click="toggleSidebar"/>


    <div t-if="state.godSearchOpen" class="tcrm-cc-palette-overlay" t-on-click="closeGodSearch">
        <div class="tcrm-cc-palette" t-on-click.stop="">
            <div class="tcrm-cc-palette__head">
                <i class="fa-solid fa-bolt"/>
                <span t-esc="strGodCommand"/>
                <kbd class="tcrm-cc-kbd">Ctrl</kbd><kbd class="tcrm-cc-kbd">K</kbd>
            </div>
            <input type="search" class="tcrm-cc-palette__input" autofocus="autofocus" t-att-placeholder="strGodSearchPlaceholder" t-att-value="state.godSearchQuery" t-on-input="onGodSearchInput" t-on-keydown="onGodSearchKeydown"/>
            <div t-if="state.godSearchLoading" class="tcrm-cc-palette__hint">…</div>
            <div t-elif="state.godSearchResults" class="tcrm-cc-palette__results">
                <t t-if="state.godSearchResults.tenants.length">
                    <div class="tcrm-cc-palette__group" t-esc="strGrpTenants"/>
                    <button type="button" class="tcrm-cc-palette__item" t-foreach="state.godSearchResults.tenants" t-as="row" t-key="row.id" t-on-click="() =&gt; this.selectGodTenant(row.id)">
                        <i class="fa-solid fa-building"/><span t-esc="row.name"/>
                    </button>
                </t>
                <t t-if="state.godSearchResults.invoices.length">
                    <div class="tcrm-cc-palette__group" t-esc="strGrpInvoices"/>
                    <button type="button" class="tcrm-cc-palette__item" t-foreach="state.godSearchResults.invoices" t-as="row" t-key="row.id" t-on-click="() =&gt; this.selectGodInvoice(row)">
                        <i class="fa-solid fa-file-invoice"/><span t-esc="row.name"/> — <span t-esc="row.tenant_name"/>
                    </button>
                </t>
                <t t-if="state.godSearchResults.users.length">
                    <div class="tcrm-cc-palette__group" t-esc="strGrpUsers"/>
                    <button type="button" class="tcrm-cc-palette__item" t-foreach="state.godSearchResults.users" t-as="row" t-key="row.id" t-on-click="() =&gt; this.selectGodUser(row.id)">
                        <i class="fa-solid fa-user"/><span t-esc="row.name"/> <span class="tcrm-cc-text-muted">(<t t-esc="row.login"/>)</span>
                    </button>
                </t>
                <div t-if="!state.godSearchLoading and state.godSearchQuery.length &gt;= 2 and !state.godSearchResults.tenants.length and !state.godSearchResults.invoices.length and !state.godSearchResults.users.length" class="tcrm-cc-palette__empty" t-esc="strGodNoMatches"/>
            </div>
            <div t-else="" class="tcrm-cc-palette__hint" t-esc="strGodTypeTwo"/>
        </div>
    </div>


    <main class="tcrm-cc-main">

        <header class="tcrm-cc-header">
            <button type="button" class="tcrm-cc-header__toggle" t-on-click="toggleSidebar" title="Toggle sidebar">
                <i class="fa-solid fa-bars"/>
            </button>
            <h1 class="tcrm-cc-header__title">
                <t t-if="state.screen === 'dashboard'">God View Dashboard</t>
                <t t-elif="state.screen === 'tenants'">Tenant Hub</t>
                <t t-elif="state.screen === 'tenant_detail'">Tenant 360°</t>
                <t t-elif="state.screen === 'users'">User Management</t>
                <t t-elif="state.screen === 'access'">Access Management</t>
                <t t-elif="state.screen === 'financials'">Financial Console</t>
                <t t-elif="state.screen === 'technical'">Technical Console</t>
                <t t-elif="state.screen === 'db_console'">DB Management</t>
                <t t-elif="state.screen === 'analytics'">Analytics &amp; Reports</t>
                <t t-elif="state.screen === 'portfolio'" t-esc="strPortfolioPageTitle"/>
            </h1>
            <div class="tcrm-cc-header__actions">
                <button type="button" class="tcrm-cc-btn tcrm-cc-btn--ghost tcrm-cc-theme-toggle" t-on-click="toggleTheme">
                    <i t-if="state.themeLight" class="fa-solid fa-moon" title="Dark mode"/>
                    <i t-else="" class="fa-solid fa-sun" title="Light mode"/>
                    <span t-if="state.themeLight">Dark mode</span>
                    <span t-else="">Light mode</span>
                </button>
                <button type="button" class="tcrm-cc-btn tcrm-cc-btn--primary" t-on-click="openCreateTenant">
                    <i class="fa-solid fa-plus"/> New Tenant
                </button>
            </div>
        </header>


        <t t-if="state.loading and !state.dashboard and !state.tenants.length">
            <div class="tcrm-cc-loading">
                <div class="tcrm-cc-spinner"/>
                <span>Loading data…</span>
            </div>
        </t>


        <t t-if="state.screen === 'dashboard'">
            <div class="tcrm-cc-content">
                <t t-if="state.dashboard">

                    <div class="tcrm-cc-kpi-grid tcrm-cc-kpi-grid--statcards">
                        <TcrmStatCard label="lblKpiGdv" value="fmtMoney(state.dashboard.gdv, state.dashboard.currency)" spark="state.dashboard.sparklines.gdv" deltaText="deltaLine(state.dashboard.deltas.gdv_pct)" t-att-deltaPositive="isDeltaPositive(state.dashboard.deltas.gdv_pct)" t-att-iconClass="'fa-solid fa-building'" t-att-accent="'#0c1e3d'"/>
                        <TcrmStatCard label="lblKpiHealth" value="fmtPct(state.dashboard.tenant_health_pct)" sub="kpiSubHealth" spark="state.dashboard.sparklines.health" deltaText="deltaLine(state.dashboard.deltas.health_pct)" t-att-deltaPositive="isDeltaPositive(state.dashboard.deltas.health_pct)" t-att-iconClass="'fa-solid fa-heart-pulse'" t-att-accent="'#065f46'"/>
                        <TcrmStatCard label="lblKpiMrr" value="fmtMoney(state.dashboard.mrr, state.dashboard.currency)" sub="kpiSubMrr" spark="state.dashboard.sparklines.mrr" deltaText="deltaLine(state.dashboard.deltas.mrr_pct)" t-att-deltaPositive="isDeltaPositive(state.dashboard.deltas.mrr_pct)" t-att-iconClass="'fa-solid fa-sack-dollar'" t-att-accent="'#5b21b6'"/>
                        <TcrmStatCard label="lblKpiUsers" value="fmtNum(state.dashboard.total_users)" spark="state.dashboard.sparklines.users" deltaText="deltaLine(state.dashboard.deltas.users_pct)" t-att-deltaPositive="isDeltaPositive(state.dashboard.deltas.users_pct)" t-att-iconClass="'fa-solid fa-users'" t-att-accent="'#9f1239'"/>
                    </div>


                    <div class="tcrm-cc-utility-bar" role="toolbar" t-att-aria-label="lblUtilityBar">
                        <button type="button" class="tcrm-cc-utility-btn" t-on-click="() =&gt; this.navigateTo('tenants')">
                            <i class="fa-solid fa-building"/><span t-esc="strUtilTenants"/>
                        </button>
                        <button type="button" class="tcrm-cc-utility-btn" t-on-click="() =&gt; this.navigateTo('financials')">
                            <i class="fa-solid fa-coins"/><span t-esc="strUtilFinancials"/>
                        </button>
                        <button type="button" class="tcrm-cc-utility-btn" t-on-click="() =&gt; this.navigateTo('analytics')">
                            <i class="fa-solid fa-chart-line"/><span t-esc="strUtilAnalytics"/>
                        </button>
                        <button type="button" class="tcrm-cc-utility-btn" t-on-click="() =&gt; this.navigateTo('users')">
                            <i class="fa-solid fa-users"/><span t-esc="strUtilUsers"/>
                        </button>
                        <button type="button" class="tcrm-cc-utility-btn" t-on-click="() =&gt; this.navigateTo('access')">
                            <i class="fa-solid fa-shield-halved"/><span t-esc="strUtilAccess"/>
                        </button>
                        <button type="button" class="tcrm-cc-utility-btn tcrm-cc-utility-btn--accent" t-on-click="openCreateTenant">
                            <i class="fa-solid fa-plus"/><span t-esc="strUtilNewTenant"/>
                        </button>
                        <span class="tcrm-cc-utility-hint"><kbd class="tcrm-cc-kbd">Ctrl</kbd><kbd class="tcrm-cc-kbd">K</kbd> <t t-esc="strUtilCommand"/></span>
                    </div>


                    <div class="tcrm-cc-dashboard-split">
                        <div class="tcrm-cc-card tcrm-cc-metric-panel">
                            <div class="tcrm-cc-card__header">
                                <i class="fa-solid fa-table-cells"/>
                                <span t-esc="lblMetricSnapshot"/>
                            </div>
                            <div class="tcrm-cc-card__body tcrm-cc-metric-panel__body">
                                <table class="tcrm-cc-metric-table">
                                    <tbody>
                                        <tr>
                                            <td class="tcrm-cc-metric-table__icon"><i class="fa-solid fa-chart-line"/></td>
                                            <td class="tcrm-cc-metric-table__lab" t-esc="lblCollected30"/>
                                            <td class="tcrm-cc-metric-table__val"><t t-esc="fmtMoney(state.dashboard.total_revenue_30d, state.dashboard.currency)"/></td>
                                            <td class="tcrm-cc-metric-table__bar"><div class="tcrm-cc-vbar"><div class="tcrm-cc-vbar__fill" t-att-style="'height:' + snapshotBarWidth('col30') + '%'"/></div></td>
                                        </tr>
                                        <tr>
                                            <td class="tcrm-cc-metric-table__icon"><i class="fa-solid fa-file-invoice-dollar"/></td>
                                            <td class="tcrm-cc-metric-table__lab" t-esc="lblOpenInvoices"/>
                                            <td class="tcrm-cc-metric-table__val">
                                                <t t-esc="fmtNum(state.dashboard.open_invoices_count)"/>
                                                <span class="tcrm-cc-text-muted"> · <t t-esc="fmtMoney(state.dashboard.open_invoices_total || 0, state.dashboard.currency)"/></span>
                                            </td>
                                            <td class="tcrm-cc-metric-table__bar"><div class="tcrm-cc-vbar"><div class="tcrm-cc-vbar__fill tcrm-cc-vbar__fill--amber" t-att-style="'height:' + snapshotBarWidth('open') + '%'"/></div></td>
                                        </tr>
                                        <tr>
                                            <td class="tcrm-cc-metric-table__icon"><i class="fa-solid fa-hourglass-half"/></td>
                                            <td class="tcrm-cc-metric-table__lab" t-esc="lblTrials"/>
                                            <td class="tcrm-cc-metric-table__val"><t t-esc="fmtNum(state.dashboard.trial_subscriptions_count || 0)"/></td>
                                            <td class="tcrm-cc-metric-table__bar"><div class="tcrm-cc-vbar"><div class="tcrm-cc-vbar__fill tcrm-cc-vbar__fill--violet" t-att-style="'height:' + snapshotBarWidth('trial') + '%'"/></div></td>
                                        </tr>
                                        <tr>
                                            <td class="tcrm-cc-metric-table__icon"><i class="fa-solid fa-triangle-exclamation"/></td>
                                            <td class="tcrm-cc-metric-table__lab" t-esc="lblPastDueSubs"/>
                                            <td class="tcrm-cc-metric-table__val"><t t-esc="fmtNum(state.dashboard.past_due_subscriptions_count || 0)"/></td>
                                            <td class="tcrm-cc-metric-table__bar"><div class="tcrm-cc-vbar"><div class="tcrm-cc-vbar__fill tcrm-cc-vbar__fill--danger" t-att-style="'height:' + snapshotBarWidth('past') + '%'"/></div></td>
                                        </tr>
                                        <tr>
                                            <td class="tcrm-cc-metric-table__icon"><i class="fa-solid fa-ban"/></td>
                                            <td class="tcrm-cc-metric-table__lab" t-esc="lblSuspended"/>
                                            <td class="tcrm-cc-metric-table__val"><t t-esc="fmtNum(state.dashboard.suspended_subscriptions_count || 0)"/></td>
                                            <td class="tcrm-cc-metric-table__bar"><div class="tcrm-cc-vbar"><div class="tcrm-cc-vbar__fill tcrm-cc-vbar__fill--muted" t-att-style="'height:' + snapshotBarWidth('sus') + '%'"/></div></td>
                                        </tr>
                                    </tbody>
                                </table>
                            </div>
                        </div>
                        <div class="tcrm-cc-dashboard-split__right">
                            <TcrmTenantMap markers="state.dashboard.map_markers" title="lblMapTenants" onMarkerSelect.bind="onMapTenantClick"/>
                            <div class="tcrm-cc-card tcrm-cc-vps-card">
                                <TcrmHealthGauges title="vpsPanelTitle" vps="state.vpsMetrics"/>
                            </div>
                        </div>
                    </div>

                    <div class="tcrm-cc-grid-2 tcrm-cc-dashboard-mid">

                        <div class="tcrm-cc-card">
                            <div class="tcrm-cc-card__header">
                                <i class="fa-solid fa-clock-rotate-left"/>
                                <span t-esc="lblLiveActivity"/>
                            </div>
                            <div class="tcrm-cc-card__body">
                                <t t-if="state.dashboard.activities and state.dashboard.activities.length">
                                    <table class="tcrm-cc-table">
                                        <thead><tr>
                                            <th t-esc="strThEvent"/><th t-esc="strThTenant"/><th t-esc="strThStatus"/><th t-esc="strThTime"/>
                                        </tr></thead>
                                        <tbody>
                                            <t t-foreach="state.dashboard.activities" t-as="a" t-key="a.id + '_' + a.type">
                                                <tr>
                                                    <td><t t-esc="a.event"/></td>
                                                    <td class="tcrm-cc-tenant-cell">
                                                        <span t-esc="a.tenant_name"/>
                                                        <button t-if="a.tenant_id" type="button" class="tcrm-cc-ghost-btn" t-att-title="strGhostTitle" t-on-click="() =&gt; this.onTenantWorkspace(a.tenant_id)">
                                                            <i class="fa-solid fa-ghost"/>
                                                        </button>
                                                    </td>
                                                    <td><span t-att-class="'tcrm-badge ' + stateBadgeClass(a.status)" t-esc="stateLabel(a.status)"/></td>
                                                    <td class="tcrm-cc-text-muted"><t t-esc="dashboardShortDate(a.timestamp)"/></td>
                                                </tr>
                                            </t>
                                        </tbody>
                                    </table>
                                </t>
                                <t t-else="">
                                    <div class="tcrm-cc-empty" t-esc="strNoActivity"/>
                                </t>
                            </div>
                        </div>


                        <div t-att-class="'tcrm-cc-card tcrm-cc-card--alert' + (state.dashboard.overdue_count ? ' tcrm-cc-card--pulse' : '')">
                            <div class="tcrm-cc-card__header">
                                <i class="fa-solid fa-bell tcrm-cc-card__header-icon--danger"/>
                                <span t-esc="lblBillingAlerts"/>
                                <t t-if="state.dashboard.overdue_count">
                                    <span class="tcrm-badge tcrm-badge-danger"><t t-esc="state.dashboard.overdue_count"/> <t t-esc="strOverdue"/></span>
                                </t>
                            </div>
                            <div class="tcrm-cc-card__body">
                                <t t-if="state.dashboard.overdue_total and state.dashboard.overdue_count">
                                    <div class="tcrm-cc-alert-summary">
                                        <span class="tcrm-cc-alert-summary__label" t-esc="lblAtRiskAr"/>
                                        <span class="tcrm-cc-alert-summary__value"><t t-esc="fmtMoney(state.dashboard.overdue_total, state.dashboard.currency)"/></span>
                                    </div>
                                </t>
                                <t t-if="state.dashboard.alerts and state.dashboard.alerts.length">
                                    <t t-foreach="state.dashboard.alerts" t-as="alert" t-key="alert.id">
                                        <div class="tcrm-cc-alert-item">
                                            <div class="tcrm-cc-alert-item__header">
                                                <span class="tcrm-cc-alert-item__tenant" t-esc="alert.tenant_name"/>
                                                <span class="tcrm-cc-alert-item__amount"><t t-esc="fmtMoney(alert.amount, alert.currency)"/></span>
                                            </div>
                                            <div class="tcrm-cc-alert-item__msg"><t t-esc="alert.message"/></div>
                                            <div class="tcrm-cc-alert-item__actions">
                                                <button type="button" class="tcrm-cc-btn tcrm-cc-btn--sm tcrm-cc-btn--danger" t-on-click="() =&gt; this.openTenantDetail(alert.tenant_id)">
                                                    <t t-esc="strInvestigate"/>
                                                </button>
                                            </div>
                                        </div>
                                    </t>
                                </t>
                                <t t-else="">
                                    <div class="tcrm-cc-empty tcrm-cc-empty--success">
                                        <i class="fa-solid fa-circle-check"/>
                                        <span t-esc="strAllClear"/>
                                    </div>
                                </t>
                            </div>
                        </div>
                    </div>


                    <div class="tcrm-cc-grid-2 tcrm-cc-dashboard-bottom">
                        <div class="tcrm-cc-card">
                            <div class="tcrm-cc-card__header">
                                <i class="fa-solid fa-rocket"/>
                                <span t-esc="lblRecentTenants"/>
                            </div>
                            <div class="tcrm-cc-card__body">
                                <t t-if="state.dashboard.recent_tenants and state.dashboard.recent_tenants.length">
                                    <table class="tcrm-cc-table tcrm-cc-table--compact">
                                        <thead><tr>
                                            <th>Tenant</th><th>State</th><th>Plan</th><th>Users</th><th>Added</th><th/>
                                        </tr></thead>
                                        <tbody>
                                            <t t-foreach="state.dashboard.recent_tenants" t-as="rt" t-key="rt.id">
                                                <tr>
                                                    <td><t t-esc="rt.name"/></td>
                                                    <td><span t-att-class="'tcrm-badge ' + stateBadgeClass(rt.state)" t-esc="stateLabel(rt.state)"/></td>
                                                    <td class="tcrm-cc-text-muted"><t t-esc="rt.package or '—'"/></td>
                                                    <td><t t-esc="fmtNum(rt.user_count)"/></td>
                                                    <td class="tcrm-cc-text-muted"><t t-esc="dashboardShortDate(rt.create_date)"/></td>
                                                    <td>
                                                        <button type="button" class="tcrm-cc-btn tcrm-cc-btn--sm tcrm-cc-btn--ghost" t-on-click="() =&gt; this.openTenantDetail(rt.id)">View</button>
                                                    </td>
                                                </tr>
                                            </t>
                                        </tbody>
                                    </table>
                                </t>
                                <t t-else="">
                                    <div class="tcrm-cc-empty" t-esc="strNoTenantsYet"/>
                                </t>
                            </div>
                        </div>
                        <div class="tcrm-cc-card">
                            <div class="tcrm-cc-card__header">
                                <i class="fa-solid fa-layer-group"/>
                                <span t-esc="lblPlansPipeline"/>
                            </div>
                            <div class="tcrm-cc-card__body">
                                <t t-if="state.dashboard.package_mix and state.dashboard.package_mix.length">
                                    <div class="tcrm-cc-plans-split">
                                        <div class="tcrm-cc-donut-wrap">
                                            <svg class="tcrm-cc-donut" viewBox="0 0 140 140" aria-hidden="true">
                                                <t t-foreach="packageDonutSegments(state.dashboard.package_mix)" t-as="seg" t-key="seg.name">
                                                    <path t-att-d="seg.d" t-att-fill="seg.color" stroke="var(--cc-surface)" stroke-width="1"/>
                                                </t>
                                            </svg>
                                            <div class="tcrm-cc-donut-center">
                                                <div class="tcrm-cc-donut-center__v"><t t-esc="fmtNum(state.dashboard.active_subscriptions_count || 0)"/></div>
                                                <div class="tcrm-cc-donut-center__l" t-esc="strActiveSubs"/>
                                            </div>
                                        </div>
                                        <div class="tcrm-cc-plans-bars">
                                            <div class="tcrm-cc-mix-legend"><span t-esc="lblDonutMix"/></div>
                                            <t t-foreach="state.dashboard.package_mix" t-as="pkg" t-key="pkg.name">
                                                <div class="tcrm-cc-mix-row">
                                                    <div class="tcrm-cc-mix-row__head">
                                                        <span class="tcrm-cc-mix-row__name" t-esc="pkg.name"/>
                                                        <span class="tcrm-cc-mix-row__count" t-esc="pkg.count"/>
                                                    </div>
                                                    <div class="tcrm-cc-mix-track">
                                                        <div class="tcrm-cc-mix-fill" t-att-style="'width: ' + mixBarWidth(pkg) + '%'"/>
                                                    </div>
                                                </div>
                                            </t>
                                        </div>
                                    </div>
                                </t>
                                <t t-else="">
                                    <div class="tcrm-cc-empty" t-esc="strNoPlans"/>
                                </t>
                            </div>
                        </div>
                    </div>
                </t>
            </div>
        </t>


        <t t-if="state.screen === 'portfolio'">
            <div class="tcrm-cc-content tcrm-cc-ms-root">
                <t t-if="state.dashboard">
                    <div class="tcrm-cc-ms-layout">
                        <div class="tcrm-cc-ms-center">
                            <div class="tcrm-cc-ms-profile">
                                <div class="tcrm-cc-ms-profile__avatar"><i class="fa-solid fa-user-tie"/></div>
                                <div>
                                    <div class="tcrm-cc-ms-profile__title" t-esc="strExecutiveSuiteTitle"/>
                                    <div class="tcrm-cc-ms-profile__tag" t-esc="strCommandCenterTag"/>
                                </div>
                            </div>
                            <div class="tcrm-cc-ms-topbar">
                                <div class="tcrm-cc-ms-topbar__left">
                                    <span class="tcrm-cc-ms-mark" t-esc="strMasterSuiteMark"/>
                                    <nav class="tcrm-cc-ms-tabs" aria-label="Portfolio">
                                        <span class="tcrm-cc-ms-tab tcrm-cc-ms-tab--active" t-esc="strNavOverview"/>
                                        <button type="button" class="tcrm-cc-ms-tab" t-esc="strNavAssets" t-on-click="() =&gt; this.navigateTo('financials')"/>
                                        <button type="button" class="tcrm-cc-ms-tab" t-esc="strNavCapital" t-on-click="() =&gt; this.navigateTo('analytics')"/>
                                    </nav>
                                </div>
                                <div class="tcrm-cc-ms-topbar__actions">
                                    <div class="tcrm-cc-ms-search">
                                        <i class="fa-solid fa-magnifying-glass tcrm-cc-ms-search__icon"/>
                                        <input type="text" class="tcrm-cc-ms-search__input" t-att-placeholder="strPortfolioSearchPh" t-att-readonly="true" t-on-click="openGodSearchFromPortfolio" t-on-focus="openGodSearchFromPortfolio"/>
                                    </div>
                                    <button type="button" class="tcrm-cc-ms-icon-btn" title="Notifications"><i class="fa-solid fa-bell"/></button>
                                    <button type="button" class="tcrm-cc-ms-icon-btn" title="Apps"><i class="fa-solid fa-grip"/></button>
                                    <button type="button" class="tcrm-cc-ms-icon-btn tcrm-cc-ms-icon-btn--round"><i class="fa-solid fa-circle-user"/></button>
                                </div>
                            </div>
                            <div class="tcrm-cc-ms-toolbar">
                                <div class="tcrm-cc-ms-toolbar__left">
                                    <div class="tcrm-cc-ms-seg" role="group">
                                        <button type="button" t-att-class="'tcrm-cc-ms-seg__btn ' + (state.portfolioRange === '30d' ? 'is-active' : '')" t-esc="strRange30" t-on-click="() =&gt; this.setPortfolioRange('30d')"/>
                                        <button type="button" t-att-class="'tcrm-cc-ms-seg__btn ' + (state.portfolioRange === 'quarter' ? 'is-active' : '')" t-esc="strRangeQuarter" t-on-click="() =&gt; this.setPortfolioRange('quarter')"/>
                                        <button type="button" t-att-class="'tcrm-cc-ms-seg__btn ' + (state.portfolioRange === 'custom' ? 'is-active' : '')" t-esc="strRangeCustom" t-on-click="() =&gt; this.setPortfolioRange('custom')"/>
                                    </div>
                                </div>
                                <div class="tcrm-cc-ms-toolbar__right">
                                    <div class="tcrm-cc-ms-ghost" t-on-click="togglePortfolioGhostMode" role="button" t-att-aria-pressed="state.portfolioGhostMode">
                                        <span class="tcrm-cc-ms-ghost__lab" t-esc="strGhostMode"/>
                                        <span t-att-class="'tcrm-cc-ms-ghost__track ' + (state.portfolioGhostMode ? 'is-on' : '')">
                                            <span class="tcrm-cc-ms-ghost__knob"/>
                                        </span>
                                    </div>
                                    <button type="button" class="tcrm-cc-ms-link-btn" t-on-click="() =&gt; this.navigateTo('access')">
                                        <i class="fa-solid fa-filter"/><span t-esc="strAdvancedFilters"/>
                                    </button>
                                </div>
                            </div>
                            <div class="tcrm-cc-ms-scroll">
                                <section class="tcrm-cc-ms-bento" aria-label="KPI">
                                    <div class="tcrm-cc-ms-card tcrm-cc-ms-card--bento">
                                        <div class="tcrm-cc-ms-card__top">
                                            <span class="tcrm-cc-ms-kicker" t-esc="strTotalPortfolioGdv"/>
                                            <span t-if="fmtDeltaShort(state.dashboard.deltas.gdv_pct)" t-att-class="'tcrm-cc-ms-pill ' + deltaPillClass(state.dashboard.deltas.gdv_pct)">
                                                <i t-att-class="'fa-solid ' + (isDeltaPositive(state.dashboard.deltas.gdv_pct) === true ? 'fa-arrow-trend-up' : (isDeltaPositive(state.dashboard.deltas.gdv_pct) === false ? 'fa-arrow-trend-down' : 'fa-minus'))"/>
                                                <t t-esc="fmtDeltaShort(state.dashboard.deltas.gdv_pct)"/>
                                            </span>
                                        </div>
                                        <h2 class="tcrm-cc-ms-stat"><t t-esc="fmtMoney(state.dashboard.gdv, state.dashboard.currency)"/></h2>
                                        <div class="tcrm-cc-ms-mini-spark">
                                            <svg class="tcrm-cc-ms-mini-spark__svg" viewBox="0 0 120 32" preserveAspectRatio="none" t-if="state.dashboard.sparklines.gdv and state.dashboard.sparklines.gdv.length">
                                                <path t-att-d="portfolioSparkPath('gdv')" fill="none" stroke="currentColor" stroke-width="1.75" vector-effect="non-scaling-stroke"/>
                                            </svg>
                                            <div class="tcrm-cc-ms-mini-spark__dot"/>
                                        </div>
                                    </div>
                                    <div class="tcrm-cc-ms-card tcrm-cc-ms-card--bento">
                                        <div class="tcrm-cc-ms-card__top">
                                            <span class="tcrm-cc-ms-kicker" t-esc="strActiveTenantHealth"/>
                                            <span t-if="portfolioHealthLowCount()" class="tcrm-cc-ms-pill tcrm-cc-ms-pill--warn">
                                                <i class="fa-solid fa-triangle-exclamation"/>
                                                <t t-esc="portfolioHealthLowCount()"/> <t t-esc="strLowSuffix"/>
                                            </span>
                                            <span t-else="" class="tcrm-cc-ms-pill tcrm-cc-ms-pill--ok" t-esc="strStableHealth"/>
                                        </div>
                                        <h2 class="tcrm-cc-ms-stat"><t t-esc="fmtPct(state.dashboard.tenant_health_pct)"/></h2>
                                        <div class="tcrm-cc-ms-health-track">
                                            <div class="tcrm-cc-ms-health-fill" t-att-style="'width:' + state.dashboard.tenant_health_pct + '%'"/>
                                        </div>
                                    </div>
                                    <div class="tcrm-cc-ms-card tcrm-cc-ms-card--bento">
                                        <div class="tcrm-cc-ms-card__top">
                                            <span class="tcrm-cc-ms-kicker" t-esc="strAiEngineLoad"/>
                                            <i class="fa-solid fa-bolt tcrm-cc-ms-bolt"/>
                                        </div>
                                        <h2 class="tcrm-cc-ms-stat"><t t-esc="fmtAiLatency()"/></h2>
                                        <p class="tcrm-cc-ms-micro" t-esc="strAiLatencySub"/>
                                    </div>
                                    <div class="tcrm-cc-ms-card tcrm-cc-ms-card--bento">
                                        <div class="tcrm-cc-ms-card__top">
                                            <span class="tcrm-cc-ms-kicker" t-esc="lblKpiMrr"/>
                                            <span t-if="fmtDeltaShort(state.dashboard.deltas.mrr_pct)" t-att-class="'tcrm-cc-ms-pill ' + deltaPillClass(state.dashboard.deltas.mrr_pct)" t-esc="fmtDeltaShort(state.dashboard.deltas.mrr_pct)"/>
                                        </div>
                                        <h2 class="tcrm-cc-ms-stat"><t t-esc="fmtMoney(state.dashboard.mrr, state.dashboard.currency)"/></h2>
                                        <div class="tcrm-cc-ms-mrr-bars">
                                            <t t-foreach="portfolioMrrBarHeights()" t-as="ht" t-key="ht_index">
                                                <div class="tcrm-cc-ms-mrr-bar" t-att-style="'height:' + ht + '%'"/>
                                            </t>
                                        </div>
                                    </div>
                                </section>
                                <section class="tcrm-cc-ms-activity-block">
                                    <div class="tcrm-cc-ms-activity-head">
                                        <h3 class="tcrm-cc-ms-activity-title">
                                            <i class="fa-solid fa-rss tcrm-cc-ms-activity-ico"/>
                                            <span t-esc="strLiveActivityStream"/>
                                        </h3>
                                        <button type="button" class="tcrm-cc-ms-dl" t-esc="strDownloadLog" t-on-click="downloadPortfolioActivityLog"/>
                                    </div>
                                    <div class="tcrm-cc-ms-table-wrap">
                                        <t t-if="state.dashboard.activities and state.dashboard.activities.length">
                                            <table class="tcrm-cc-ms-table">
                                                <thead>
                                                    <tr>
                                                        <th t-esc="strThEvent"/>
                                                        <th t-esc="strThTenantEntity"/>
                                                        <th t-esc="strThStatus"/>
                                                        <th class="tcrm-cc-ms-table__th-right" t-esc="strThTime"/>
                                                    </tr>
                                                </thead>
                                                <tbody>
                                                    <t t-foreach="state.dashboard.activities" t-as="a" t-key="a.id + '_' + a.type">
                                                        <tr>
                                                            <td>
                                                                <div class="tcrm-cc-ms-ev">
                                                                    <i t-att-class="portfolioActivityIconClass(a)"/>
                                                                    <span class="tcrm-cc-ms-ev__txt" t-esc="a.event"/>
                                                                </div>
                                                            </td>
                                                            <td>
                                                                <div class="tcrm-cc-ms-tenant">
                                                                    <span class="tcrm-cc-ms-tenant__badge" t-esc="tenantInitials(a.tenant_name)"/>
                                                                    <span t-esc="a.tenant_name"/>
                                                                    <button t-if="a.tenant_id" type="button" class="tcrm-cc-ghost-btn tcrm-cc-ms-ghost-inline" t-att-title="strGhostTitle" t-on-click="() =&gt; this.onTenantWorkspace(a.tenant_id)">
                                                                        <i class="fa-solid fa-ghost"/>
                                                                    </button>
                                                                </div>
                                                            </td>
                                                            <td>
                                                                <span t-att-class="'tcrm-cc-ms-status tcrm-badge ' + stateBadgeClass(a.status)" t-esc="stateLabel(a.status)"/>
                                                            </td>
                                                            <td class="tcrm-cc-ms-table__td-right"><span class="tcrm-cc-ms-time" t-esc="dashboardRelativeTime(a.timestamp)"/></td>
                                                        </tr>
                                                    </t>
                                                </tbody>
                                            </table>
                                        </t>
                                        <t t-else="">
                                            <div class="tcrm-cc-empty" t-esc="strNoActivity"/>
                                        </t>
                                    </div>
                                </section>
                            </div>
                        </div>
                        <aside class="tcrm-cc-ms-rail" aria-label="Alerts and AI">
                            <div class="tcrm-cc-ms-rail__alerts">
                                <h3 class="tcrm-cc-ms-rail__h">
                                    <i class="fa-solid fa-triangle-exclamation"/>
                                    <span t-esc="strSystemRedAlerts"/>
                                </h3>
                                <t t-if="state.dashboard.alerts and state.dashboard.alerts.length">
                                    <t t-foreach="state.dashboard.alerts" t-as="alert" t-key="alert.id">
                                        <div t-if="alert_index &lt; 2" t-att-class="'tcrm-cc-ms-alert ' + (alert.severity === 'critical' ? 'tcrm-cc-ms-alert--crit' : '')" t-on-click="() =&gt; this.openTenantDetail(alert.tenant_id)">
                                            <p class="tcrm-cc-ms-alert__title">
                                                <t t-esc="alert.tenant_name"/> — <t t-esc="fmtMoney(alert.amount, alert.currency)"/>
                                            </p>
                                            <p class="tcrm-cc-ms-alert__msg" t-esc="alert.message"/>
                                            <button type="button" class="tcrm-cc-ms-alert__cta" t-on-click.stop="() =&gt; this.openTenantDetail(alert.tenant_id)">
                                                <span t-esc="strIntervene"/> <i class="fa-solid fa-arrow-right"/>
                                            </button>
                                        </div>
                                    </t>
                                </t>
                                <t t-else="">
                                    <div class="tcrm-cc-ms-alert tcrm-cc-ms-alert--empty">
                                        <p class="tcrm-cc-ms-alert__msg" t-esc="strAllClear"/>
                                    </div>
                                </t>
                            </div>
                            <div class="tcrm-cc-ms-ai">
                                <div class="tcrm-cc-ms-ai__head">
                                    <h4><i class="fa-solid fa-robot"/><span t-esc="strTcrmAiInsight"/></h4>
                                    <span class="tcrm-cc-ms-ai__live"/>
                                </div>
                                <div class="tcrm-cc-ms-ai__thread">
                                    <t t-foreach="state.portfolioAiMessages" t-as="m" t-key="m_index">
                                        <div t-att-class="'tcrm-cc-ms-ai__row ' + (m.role === 'user' ? 'is-user' : 'is-ai')">
                                            <div t-if="m.role !== 'user'" class="tcrm-cc-ms-ai__avatar"><i class="fa-solid fa-bolt"/></div>
                                            <div class="tcrm-cc-ms-ai__bubble" t-esc="m.text"/>
                                        </div>
                                    </t>
                                </div>
                                <form class="tcrm-cc-ms-ai__form" t-on-submit.prevent="submitPortfolioAi">
                                    <input type="text" class="tcrm-cc-ms-ai__input" t-att-placeholder="strAskTcrmAi" t-att-value="state.portfolioAiInput" t-on-input="onPortfolioAiInput"/>
                                    <button type="submit" class="tcrm-cc-ms-ai__send" aria-label="Send"><i class="fa-solid fa-paper-plane"/></button>
                                </form>
                            </div>
                        </aside>
                    </div>
                    <button type="button" class="tcrm-cc-ms-fab" t-on-click="openGlobalCommandFab" t-att-title="strGlobalCommand">
                        <i class="fa-solid fa-plus"/>
                        <span class="tcrm-cc-ms-fab__tip" t-esc="strGlobalCommand"/>
                    </button>
                </t>
                <t t-else="">
                    <div class="tcrm-cc-empty" t-esc="strPortfolioNoData"/>
                </t>
            </div>
        </t>


        <t t-if="state.screen === 'tenants'">
            <div class="tcrm-cc-content">

                <div class="tcrm-cc-toolbar">
                    <div class="tcrm-cc-search">
                        <span class="material-symbols-outlined">search</span>
                        <input type="text" placeholder="Search tenants…" t-att-value="state.tenantSearch" t-on-input="onTenantSearchInput" t-on-keydown="onTenantSearchKeydown"/>
                    </div>
                    <div class="tcrm-cc-filter-chips">
                        <button t-att-class="'tcrm-cc-chip ' + (state.tenantFilterState === 'active' ? 'tcrm-cc-chip--active' : '')" t-on-click="() =&gt; this.filterTenantsByState('active')">Active</button>
                        <button t-att-class="'tcrm-cc-chip ' + (state.tenantFilterState === 'draft' ? 'tcrm-cc-chip--active' : '')" t-on-click="() =&gt; this.filterTenantsByState('draft')">Draft</button>
                    </div>
                </div>


                <t t-if="state.tenants.length">
                    <div class="tcrm-cc-tenant-grid">
                        <t t-foreach="state.tenants" t-as="t" t-key="t.id">
                            <div class="tcrm-cc-tenant-card" t-on-click="() =&gt; this.openTenantDetail(t.id)">
                                <div class="tcrm-cc-tenant-card__header">
                                    <div class="tcrm-cc-tenant-card__name"><t t-esc="t.name"/></div>
                                    <span t-att-class="'tcrm-badge ' + stateBadgeClass(t.health)" t-esc="t.health"/>
                                </div>
                                <div class="tcrm-cc-tenant-card__meta">
                                    <span><span class="material-symbols-outlined">inventory_2</span> <t t-esc="t.package"/></span>
                                    <span><span class="material-symbols-outlined">group</span> <t t-esc="t.user_count"/>/<t t-esc="t.user_limit || '8'"/></span>
                                </div>
                                <div class="tcrm-cc-tenant-card__meta">
                                    <span><span class="material-symbols-outlined">language</span> <t t-esc="t.domain || 'No domain'"/></span>
                                    <span t-att-class="'tcrm-badge ' + stateBadgeClass(t.state)"><t t-esc="stateLabel(t.state)"/></span>
                                </div>
                                <div class="tcrm-cc-tenant-card__actions" t-on-click.stop="">
                                    <button class="tcrm-cc-btn tcrm-cc-btn--sm tcrm-cc-btn--ghost" t-on-click.stop="() =&gt; this.openTenantInOdoo(t.id)">
                                        <span class="material-symbols-outlined">open_in_new</span> Edit
                                    </button>
                                    <t t-if="t.state === 'draft'">
                                        <button class="tcrm-cc-btn tcrm-cc-btn--sm tcrm-cc-btn--success" t-on-click.stop="() =&gt; this.activateTenant(t.id)">Activate</button>
                                    </t>
                                    <t t-if="t.state === 'active'">
                                        <button class="tcrm-cc-btn tcrm-cc-btn--sm tcrm-cc-btn--warning" t-on-click.stop="() =&gt; this.deactivateTenant(t.id)">Suspend</button>
                                    </t>
                                </div>
                            </div>
                        </t>
                    </div>
                </t>
                <t t-else="">
                    <div class="tcrm-cc-empty-state">
                        <span class="material-symbols-outlined">apartment</span>
                        <h3>No tenants found</h3>
                        <p>Create your first tenant to get started</p>
                        <button class="tcrm-cc-btn tcrm-cc-btn--primary" t-on-click="openCreateTenant">
                            <span class="material-symbols-outlined">add</span> New Tenant
                        </button>
                    </div>
                </t>
            </div>
        </t>


        <t t-if="state.screen === 'tenant_detail' and state.tenantDetail">
            <div class="tcrm-cc-content">
                <div class="tcrm-cc-back-bar">
                    <button class="tcrm-cc-btn tcrm-cc-btn--ghost" t-on-click="() =&gt; this.navigateTo('tenants')">
                        <span class="material-symbols-outlined">arrow_back</span> Back to Tenants
                    </button>
                </div>


                <div class="tcrm-cc-profile">
                    <div class="tcrm-cc-profile__avatar">
                        <span class="material-symbols-outlined">domain</span>
                    </div>
                    <div class="tcrm-cc-profile__info">
                        <h2><t t-esc="state.tenantDetail.name"/></h2>
                        <div class="tcrm-cc-profile__meta">
                            <span t-att-class="'tcrm-badge ' + stateBadgeClass(state.tenantDetail.state)"><t t-esc="stateLabel(state.tenantDetail.state)"/></span>
                            <span t-if="state.tenantDetail.package" class="tcrm-badge tcrm-badge-info"><t t-esc="state.tenantDetail.package"/></span>
                            <span class="tcrm-cc-text-muted">ID: <t t-esc="state.tenantDetail.id"/></span>
                        </div>
                    </div>
                    <div class="tcrm-cc-profile__actions">
                        <button class="tcrm-cc-btn tcrm-cc-btn--ghost" t-on-click="() =&gt; this.openTenantInOdoo(state.tenantDetail.id)">
                            <span class="material-symbols-outlined">open_in_new</span> Full Form
                        </button>
                        <t t-if="state.tenantDetail.state === 'draft'">
                            <button class="tcrm-cc-btn tcrm-cc-btn--success" t-on-click="() =&gt; this.activateTenant(state.tenantDetail.id)">Activate</button>
                        </t>
                        <t t-if="state.tenantDetail.state === 'active'">
                            <button class="tcrm-cc-btn tcrm-cc-btn--warning" t-on-click="() =&gt; this.deactivateTenant(state.tenantDetail.id)">Suspend</button>
                        </t>
                        <button class="tcrm-cc-btn tcrm-cc-btn--danger" t-on-click="() =&gt; this.deleteTenant(state.tenantDetail.id)">
                            <span class="material-symbols-outlined">delete</span>
                        </button>
                    </div>
                </div>


                <div class="tcrm-cc-tabs">
                    <button t-att-class="'tcrm-cc-tab ' + (state.tenantDetailTab === 'activity' ? 'tcrm-cc-tab--active' : '')" t-on-click="() =&gt; this.setTenantDetailTab('activity')">Overview</button>
                    <button t-att-class="'tcrm-cc-tab ' + (state.tenantDetailTab === 'users' ? 'tcrm-cc-tab--active' : '')" t-on-click="() =&gt; this.setTenantDetailTab('users')">Users (<t t-esc="state.tenantDetail.user_count"/>)</button>
                    <button t-att-class="'tcrm-cc-tab ' + (state.tenantDetailTab === 'modules' ? 'tcrm-cc-tab--active' : '')" t-on-click="() =&gt; this.setTenantDetailTab('modules')">Modules</button>
                    <button t-att-class="'tcrm-cc-tab ' + (state.tenantDetailTab === 'financials' ? 'tcrm-cc-tab--active' : '')" t-on-click="() =&gt; this.setTenantDetailTab('financials')">Financials</button>
                    <button t-att-class="'tcrm-cc-tab ' + (state.tenantDetailTab === 'domains' ? 'tcrm-cc-tab--active' : '')" t-on-click="() =&gt; this.setTenantDetailTab('domains')">Domains</button>
                </div>


                <t t-if="state.tenantDetailTab === 'activity'">
                    <div class="tcrm-cc-grid-2">
                        <div class="tcrm-cc-card">
                            <div class="tcrm-cc-card__header">Tenant Information</div>
                            <div class="tcrm-cc-card__body tcrm-cc-detail-list">
                                <div><span>Company</span><span t-esc="state.tenantDetail.company_name"/></div>
                                <div><span>Sector</span><span t-esc="state.tenantDetail.sector || 'N/A'"/></div>
                                <div><span>Email</span><span t-esc="state.tenantDetail.support_email || 'N/A'"/></div>
                                <div><span>Phone</span><span t-esc="state.tenantDetail.support_phone || 'N/A'"/></div>
                                <div><span>Primary Domain</span><span t-esc="state.tenantDetail.primary_domain || 'None'"/></div>
                                <div><span>Database</span><span t-esc="state.tenantDetail.db_name || 'Shared'"/></div>
                            </div>
                        </div>
                        <div class="tcrm-cc-card">
                            <div class="tcrm-cc-card__header">Subscriptions</div>
                            <div class="tcrm-cc-card__body">
                                <t t-if="state.tenantDetail.subscriptions and state.tenantDetail.subscriptions.length">
                                    <t t-foreach="state.tenantDetail.subscriptions" t-as="sub" t-key="sub.id">
                                        <div class="tcrm-cc-sub-item">
                                            <div><strong t-esc="sub.package"/> (<t t-esc="sub.billing_cycle"/>)</div>
                                            <div><t t-esc="fmtMoney(sub.amount, sub.currency)"/></div>
                                            <span t-att-class="'tcrm-badge ' + stateBadgeClass(sub.status)" t-esc="stateLabel(sub.status)"/>
                                        </div>
                                    </t>
                                </t>
                                <t t-else="">
                                    <div class="tcrm-cc-empty">No active subscriptions</div>
                                </t>
                            </div>
                        </div>
                    </div>
                </t>


                <t t-if="state.tenantDetailTab === 'users'">
                    <div class="tcrm-cc-card">
                        <div class="tcrm-cc-card__header">Managed Users</div>
                        <div class="tcrm-cc-card__body">
                            <t t-if="state.tenantDetail.users and state.tenantDetail.users.length">
                                <table class="tcrm-cc-table">
                                    <thead><tr>
                                        <th>User</th><th>Login</th><th>Groups</th><th>Permissions</th><th>Last Login</th><th>Actions</th>
                                    </tr></thead>
                                    <tbody>
                                        <t t-foreach="state.tenantDetail.users" t-as="u" t-key="u.id">
                                            <tr>
                                                <td><t t-esc="u.name"/></td>
                                                <td class="tcrm-cc-text-mono"><t t-esc="u.login"/></td>
                                                <td>
                                                    <t t-foreach="(u.groups || []).slice(0, 3)" t-as="g" t-key="g">
                                                        <span class="tcrm-badge tcrm-badge-muted" t-esc="g"/>
                                                    </t>
                                                </td>
                                                <td>
                                                    <t t-foreach="u.permissions || []" t-as="p" t-key="p">
                                                        <span class="tcrm-badge tcrm-badge-info" t-esc="p"/>
                                                    </t>
                                                </td>
                                                <td class="tcrm-cc-text-muted"><t t-esc="u.last_login || 'Never'"/></td>
                                                <td>
                                                    <button class="tcrm-cc-btn tcrm-cc-btn--sm tcrm-cc-btn--ghost" t-att-disabled="u.id === state.currentUserId" t-on-click="() =&gt; this.toggleUserActive(u.id, u.active)">
                                                        <t t-if="u.id === state.currentUserId">Current User</t>
                                                        <t t-elif="u.active">Deactivate</t><t t-else="">Activate</t>
                                                    </button>
                                                </td>
                                            </tr>
                                        </t>
                                    </tbody>
                                </table>
                            </t>
                            <t t-else="">
                                <div class="tcrm-cc-empty">No users found</div>
                            </t>
                        </div>
                    </div>
                </t>


                <t t-if="state.tenantDetailTab === 'modules'">
                    <div class="tcrm-cc-card">
                        <div class="tcrm-cc-card__header">Module Entitlements</div>
                        <div class="tcrm-cc-card__body">
                            <t t-if="state.tenantDetail.modules and state.tenantDetail.modules.length">
                                <div class="tcrm-cc-module-grid">
                                    <t t-foreach="state.tenantDetail.modules" t-as="m" t-key="m.id">
                                        <div class="tcrm-cc-module-card">
                                            <div class="tcrm-cc-module-card__name"><t t-esc="m.module_name"/></div>
                                            <div class="tcrm-cc-module-card__tech"><t t-esc="m.module_technical"/></div>
                                            <div class="tcrm-cc-module-card__toggle">
                                                <label class="tcrm-cc-switch">
                                                    <input type="checkbox" t-att-checked="m.state === 'allowed'" t-on-change="() =&gt; this.toggleModule(m.id)"/>
                                                    <span class="tcrm-cc-switch__slider"/>
                                                </label>
                                                <span t-att-class="'tcrm-badge ' + (m.state === 'allowed' ? 'tcrm-badge-success' : 'tcrm-badge-danger')">
                                                    <t t-esc="m.state"/>
                                                </span>
                                            </div>
                                        </div>
                                    </t>
                                </div>
                            </t>
                            <t t-else="">
                                <div class="tcrm-cc-empty">No module entitlements</div>
                            </t>
                        </div>
                    </div>
                </t>


                <t t-if="state.tenantDetailTab === 'financials'">
                    <div class="tcrm-cc-card">
                        <div class="tcrm-cc-card__header">Billing History</div>
                        <div class="tcrm-cc-card__body">
                            <t t-if="state.tenantDetail.invoices and state.tenantDetail.invoices.length">
                                <table class="tcrm-cc-table">
                                    <thead><tr>
                                        <th>Invoice</th><th>Issue Date</th><th>Due Date</th><th>Amount</th><th>Status</th><th>Actions</th>
                                    </tr></thead>
                                    <tbody>
                                        <t t-foreach="state.tenantDetail.invoices" t-as="inv" t-key="inv.id">
                                            <tr>
                                                <td><t t-esc="inv.name"/></td>
                                                <td><t t-esc="inv.issue_date"/></td>
                                                <td><t t-esc="inv.due_date"/></td>
                                                <td><t t-esc="fmtMoney(inv.amount, inv.currency)"/></td>
                                                <td><span t-att-class="'tcrm-badge ' + stateBadgeClass(inv.state)" t-esc="stateLabel(inv.state)"/></td>
                                                <td>
                                                    <t t-if="inv.state === 'open' or inv.state === 'overdue'">
                                                        <button class="tcrm-cc-btn tcrm-cc-btn--sm tcrm-cc-btn--success" t-on-click="() =&gt; this.invoiceAction(inv.id, 'mark_paid')">Mark Paid</button>
                                                    </t>
                                                    <t t-if="inv.state === 'overdue'">
                                                        <button class="tcrm-cc-btn tcrm-cc-btn--sm tcrm-cc-btn--warning" t-on-click="() =&gt; this.invoiceAction(inv.id, 'send_reminder')">Remind</button>
                                                    </t>
                                                </td>
                                            </tr>
                                        </t>
                                    </tbody>
                                </table>
                            </t>
                            <t t-else="">
                                <div class="tcrm-cc-empty">No invoices</div>
                            </t>
                        </div>
                    </div>
                </t>


                <t t-if="state.tenantDetailTab === 'domains'">
                    <div class="tcrm-cc-card">
                        <div class="tcrm-cc-card__header">Domains</div>
                        <div class="tcrm-cc-card__body">
                            <t t-if="state.tenantDetail.domains and state.tenantDetail.domains.length">
                                <table class="tcrm-cc-table">
                                    <thead><tr>
                                        <th>Domain</th><th>Primary</th><th>Verified</th><th>SSL</th><th>Actions</th>
                                    </tr></thead>
                                    <tbody>
                                        <t t-foreach="state.tenantDetail.domains" t-as="d" t-key="d.id">
                                            <tr>
                                                <td class="tcrm-cc-text-mono"><t t-esc="d.domain"/></td>
                                                <td><t t-if="d.is_primary"><span class="tcrm-badge tcrm-badge-success">Primary</span></t></td>
                                                <td><t t-if="d.verified"><span class="material-symbols-outlined" style="color: #10b981;">verified</span></t>
                                                    <t t-else=""><span class="material-symbols-outlined" style="color: #6b7280;">pending</span></t>
                                                </td>
                                                <td><span t-att-class="'tcrm-badge ' + stateBadgeClass(d.ssl_status)" t-esc="d.ssl_status"/></td>
                                                <td>
                                                    <button class="tcrm-cc-btn tcrm-cc-btn--sm tcrm-cc-btn--danger" t-on-click="() =&gt; this.deleteDomain(d.id)">Remove</button>
                                                </td>
                                            </tr>
                                        </t>
                                    </tbody>
                                </table>
                            </t>
                            <t t-else="">
                                <div class="tcrm-cc-empty">No domains configured</div>
                            </t>
                        </div>
                    </div>
                </t>
            </div>
        </t>


        <t t-if="state.screen === 'users'">
            <div class="tcrm-cc-content">
                <div class="tcrm-cc-toolbar">
                    <div class="tcrm-cc-search">
                        <span class="material-symbols-outlined">search</span>
                        <input type="text" placeholder="Filter users…" t-att-value="state.userSearch" t-on-input="onUserSearchInput" t-on-keydown="onUserSearchKeydown"/>
                    </div>
                </div>
                <div class="tcrm-cc-card">
                    <div class="tcrm-cc-card__header">
                        <span class="material-symbols-outlined">group</span>
                        Advanced User Control
                        <span class="tcrm-badge tcrm-badge-info"><t t-esc="state.users.length"/> users</span>
                    </div>
                    <div class="tcrm-cc-card__body">
                        <t t-if="state.users.length">
                            <table class="tcrm-cc-table">
                                <thead><tr>
                                    <th>User</th><th>Login</th><th>Company</th><th>Groups</th><th>Permissions</th><th>Last Login</th><th>Actions</th>
                                </tr></thead>
                                <tbody>
                                    <t t-foreach="state.users" t-as="u" t-key="u.id">
                                        <tr>
                                            <td><t t-esc="u.name"/></td>
                                            <td class="tcrm-cc-text-mono"><t t-esc="u.login"/></td>
                                            <td><t t-esc="u.company"/></td>
                                            <td>
                                                <t t-foreach="(u.groups || []).slice(0, 2)" t-as="g" t-key="g">
                                                    <span class="tcrm-badge tcrm-badge-muted" t-esc="g"/>
                                                </t>
                                            </td>
                                            <td>
                                                <t t-foreach="u.permissions || []" t-as="p" t-key="p">
                                                    <span class="tcrm-badge tcrm-badge-info" t-esc="p"/>
                                                </t>
                                            </td>
                                            <td class="tcrm-cc-text-muted"><t t-esc="u.last_login || 'Never'"/></td>
                                            <td>
                                                <button class="tcrm-cc-btn tcrm-cc-btn--sm tcrm-cc-btn--ghost" t-att-disabled="u.id === state.currentUserId" t-on-click="() =&gt; this.toggleUserActive(u.id, u.active)">
                                                    <t t-if="u.id === state.currentUserId">Current User</t>
                                                    <t t-elif="u.active">Deactivate</t><t t-else="">Activate</t>
                                                </button>
                                            </td>
                                        </tr>
                                    </t>
                                </tbody>
                            </table>
                        </t>
                        <t t-else="">
                            <div class="tcrm-cc-empty">No users found</div>
                        </t>
                    </div>
                </div>
            </div>
        </t>


        <t t-if="state.screen === 'access'">
            <div class="tcrm-cc-content">
                <t t-if="state.accessData">
                    <div class="tcrm-cc-card">
                        <div class="tcrm-cc-card__header">
                            <span class="material-symbols-outlined">security</span>
                            Tenant Access Matrix
                        </div>
                        <div class="tcrm-cc-card__body">
                            <t t-if="state.accessData.access_matrix and state.accessData.access_matrix.length">
                                <table class="tcrm-cc-table">
                                    <thead><tr>
                                        <th>Tenant</th><th>Package</th><th>Users</th><th>Modules</th>
                                    </tr></thead>
                                    <tbody>
                                        <t t-foreach="state.accessData.access_matrix" t-as="row" t-key="row.id">
                                            <tr>
                                                <td>
                                                    <a href="#" class="tcrm-cc-link" t-on-click.prevent="() =&gt; this.openTenantDetail(row.id)">
                                                        <t t-esc="row.name"/>
                                                    </a>
                                                </td>
                                                <td><t t-esc="row.package || 'None'"/></td>
                                                <td><t t-esc="row.user_count"/></td>
                                                <td>
                                                    <t t-foreach="row.modules" t-as="m" t-key="m.id">
                                                        <label class="tcrm-cc-switch tcrm-cc-switch--inline">
                                                            <input type="checkbox" t-att-checked="m.state === 'allowed'" t-on-change="() =&gt; this.toggleModuleAccess(m.id)"/>
                                                            <span class="tcrm-cc-switch__slider tcrm-cc-switch__slider--sm"/>
                                                        </label>
                                                        <span class="tcrm-cc-text-xs" t-esc="m.name"/>
                                                    </t>
                                                </td>
                                            </tr>
                                        </t>
                                    </tbody>
                                </table>
                            </t>
                        </div>
                    </div>

                    <div class="tcrm-cc-card" style="margin-top: 1.5rem;">
                        <div class="tcrm-cc-card__header">
                            <span class="material-symbols-outlined">policy</span>
                            Permission Sets
                        </div>
                        <div class="tcrm-cc-card__body">
                            <t t-if="state.accessData.permission_sets and state.accessData.permission_sets.length">
                                <table class="tcrm-cc-table">
                                    <thead><tr>
                                        <th>Name</th><th>Company</th><th>Rules</th><th>Status</th>
                                    </tr></thead>
                                    <tbody>
                                        <t t-foreach="state.accessData.permission_sets" t-as="ps" t-key="ps.id">
                                            <tr>
                                                <td><t t-esc="ps.name"/></td>
                                                <td><t t-esc="ps.company"/></td>
                                                <td>
                                                    <t t-foreach="ps.lines.slice(0, 3)" t-as="l" t-key="l.id">
                                                        <span class="tcrm-badge tcrm-badge-muted">
                                                            <t t-esc="l.model"/>.<t t-esc="l.field"/>
                                                            <t t-if="l.can_read"> R</t><t t-if="l.can_write"> W</t>
                                                        </span>
                                                    </t>
                                                    <t t-if="ps.lines.length &gt; 3">
                                                        <span class="tcrm-cc-text-muted">+<t t-esc="ps.lines.length - 3"/> more</span>
                                                    </t>
                                                </td>
                                                <td><span t-att-class="'tcrm-badge ' + (ps.active ? 'tcrm-badge-success' : 'tcrm-badge-muted')">
                                                    <t t-if="ps.active">Active</t><t t-else="">Inactive</t>
                                                </span></td>
                                            </tr>
                                        </t>
                                    </tbody>
                                </table>
                            </t>
                            <t t-else="">
                                <div class="tcrm-cc-empty">No permission sets</div>
                            </t>
                        </div>
                    </div>
                </t>
            </div>
        </t>


        <t t-if="state.screen === 'financials'">
            <div class="tcrm-cc-content">
                <t t-if="state.financials">

                    <div class="tcrm-cc-kpi-grid">
                        <div class="tcrm-cc-kpi-card tcrm-cc-kpi-card--large">
                            <div class="tcrm-cc-kpi-card__icon" style="background: #059669;">
                                <span class="material-symbols-outlined">trending_up</span>
                            </div>
                            <div class="tcrm-cc-kpi-card__body">
                                <div class="tcrm-cc-kpi-card__label">Monthly Recurring Revenue</div>
                                <div class="tcrm-cc-kpi-card__value"><t t-esc="fmtMoney(state.financials.mrr, state.financials.currency)"/></div>
                            </div>
                        </div>
                        <div class="tcrm-cc-kpi-card tcrm-cc-kpi-card--large">
                            <div class="tcrm-cc-kpi-card__icon" style="background: #dc2626;">
                                <span class="material-symbols-outlined">warning</span>
                            </div>
                            <div class="tcrm-cc-kpi-card__body">
                                <div class="tcrm-cc-kpi-card__label">At-Risk Churn</div>
                                <div class="tcrm-cc-kpi-card__value"><t t-esc="fmtMoney(state.financials.churn_value, state.financials.currency)"/></div>
                                <div class="tcrm-cc-kpi-card__sub"><t t-esc="state.financials.churn_tenants"/> tenants at risk</div>
                            </div>
                        </div>
                        <div class="tcrm-cc-kpi-card tcrm-cc-kpi-card--large">
                            <div class="tcrm-cc-kpi-card__icon" style="background: #2563eb;">
                                <span class="material-symbols-outlined">receipt_long</span>
                            </div>
                            <div class="tcrm-cc-kpi-card__body">
                                <div class="tcrm-cc-kpi-card__label">Revenue (30 days)</div>
                                <div class="tcrm-cc-kpi-card__value"><t t-esc="fmtMoney(state.financials.revenue_30d, state.financials.currency)"/></div>
                            </div>
                        </div>
                    </div>


                    <div class="tcrm-cc-card">
                        <div class="tcrm-cc-card__header">
                            <span class="material-symbols-outlined">loyalty</span>
                            Subscription Tier Hub
                        </div>
                        <div class="tcrm-cc-card__body">
                            <div class="tcrm-cc-tier-grid">
                                <t t-foreach="Object.entries(state.financials.tier_counts || {})" t-as="tier" t-key="tier[0]">
                                    <div class="tcrm-cc-tier-card">
                                        <div class="tcrm-cc-tier-card__name"><t t-esc="tier[0]"/></div>
                                        <div class="tcrm-cc-tier-card__count"><t t-esc="tier[1]"/></div>
                                        <div class="tcrm-cc-tier-card__label">subscriptions</div>
                                    </div>
                                </t>
                            </div>
                        </div>
                    </div>


                    <div class="tcrm-cc-card tcrm-cc-card--alert">
                        <div class="tcrm-cc-card__header">
                            <span class="material-symbols-outlined" style="color: #ef4444;">notification_important</span>
                            Billing Alerts
                            <span class="tcrm-badge tcrm-badge-danger"><t t-esc="state.financials.total_invoices_pending"/> pending</span>
                        </div>
                        <div class="tcrm-cc-card__body">
                            <t t-if="state.financials.billing_alerts and state.financials.billing_alerts.length">
                                <t t-foreach="state.financials.billing_alerts" t-as="ba" t-key="ba.id">
                                    <div class="tcrm-cc-alert-item">
                                        <div class="tcrm-cc-alert-item__header">
                                            <span class="tcrm-cc-alert-item__tenant"><t t-esc="ba.tenant_name"/></span>
                                            <span class="tcrm-cc-alert-item__amount"><t t-esc="fmtMoney(ba.amount, ba.currency)"/></span>
                                        </div>
                                        <div class="tcrm-cc-alert-item__msg">
                                            <t t-esc="ba.invoice_name"/>
                                            <t t-if="ba.state === 'overdue'"> — Overdue <t t-esc="ba.days_overdue"/>d</t>
                                            <t t-elif="ba.due_date"> — Due <t t-esc="ba.due_date"/></t>
                                        </div>
                                        <div class="tcrm-cc-alert-item__actions">
                                            <button class="tcrm-cc-btn tcrm-cc-btn--sm tcrm-cc-btn--warning" t-on-click="() =&gt; this.invoiceAction(ba.id, 'send_reminder')">
                                                <span class="material-symbols-outlined">notifications</span> Remind
                                            </button>
                                            <button class="tcrm-cc-btn tcrm-cc-btn--sm tcrm-cc-btn--success" t-on-click="() =&gt; this.invoiceAction(ba.id, 'mark_paid')">
                                                <span class="material-symbols-outlined">check</span> Mark Paid
                                            </button>
                                        </div>
                                    </div>
                                </t>
                            </t>
                            <t t-else="">
                                <div class="tcrm-cc-empty tcrm-cc-empty--success">
                                    <span class="material-symbols-outlined">check_circle</span> No pending invoices
                                </div>
                            </t>
                        </div>
                    </div>
                </t>
            </div>
        </t>


        <t t-if="state.screen === 'technical'">
            <div class="tcrm-cc-content">
                <t t-if="state.technical">
                    <div class="tcrm-cc-tech-hero">
                        <div class="tcrm-cc-tech-hero__id">SYSTEM_ID: TCRM-MASTER-01</div>
                        <div class="tcrm-cc-tech-hero__stats">
                            <span>Uptime: <strong t-esc="state.technical.uptime"/></span>
                            <span>Python: <strong t-esc="state.technical.python_version"/></span>
                            <span>OS: <strong t-esc="state.technical.os_info"/></span>
                            <span>DB: <strong t-esc="state.technical.db_name"/></span>
                        </div>
                    </div>


                    <div class="tcrm-cc-kpi-grid">
                        <div class="tcrm-cc-gauge-card">
                            <div class="tcrm-cc-gauge">
                                <svg viewBox="0 0 120 120">
                                    <circle cx="60" cy="60" r="52" fill="none" stroke="#1e293b" stroke-width="10"/>
                                    <circle cx="60" cy="60" r="52" fill="none" stroke="#3b82f6" stroke-width="10" stroke-dasharray="326.73" t-att-stroke-dashoffset="326.73 - (326.73 * state.technical.cpu_pct / 100)" transform="rotate(-90 60 60)"/>
                                </svg>
                                <div class="tcrm-cc-gauge__label"><t t-esc="state.technical.cpu_pct"/>%</div>
                            </div>
                            <div class="tcrm-cc-gauge-card__title">CPU</div>
                        </div>
                        <div class="tcrm-cc-gauge-card">
                            <div class="tcrm-cc-gauge">
                                <svg viewBox="0 0 120 120">
                                    <circle cx="60" cy="60" r="52" fill="none" stroke="#1e293b" stroke-width="10"/>
                                    <circle cx="60" cy="60" r="52" fill="none" stroke="#8b5cf6" stroke-width="10" stroke-dasharray="326.73" t-att-stroke-dashoffset="326.73 - (326.73 * state.technical.ram_pct / 100)" transform="rotate(-90 60 60)"/>
                                </svg>
                                <div class="tcrm-cc-gauge__label"><t t-esc="state.technical.ram_pct"/>%</div>
                            </div>
                            <div class="tcrm-cc-gauge-card__title">RAM (<t t-esc="state.technical.ram_used"/>/<t t-esc="state.technical.ram_total"/> GB)</div>
                        </div>
                        <div class="tcrm-cc-gauge-card">
                            <div class="tcrm-cc-gauge">
                                <svg viewBox="0 0 120 120">
                                    <circle cx="60" cy="60" r="52" fill="none" stroke="#1e293b" stroke-width="10"/>
                                    <circle cx="60" cy="60" r="52" fill="none" stroke="#10b981" stroke-width="10" stroke-dasharray="326.73" t-att-stroke-dashoffset="326.73 - (326.73 * state.technical.disk_pct / 100)" transform="rotate(-90 60 60)"/>
                                </svg>
                                <div class="tcrm-cc-gauge__label"><t t-esc="state.technical.disk_pct"/>%</div>
                            </div>
                            <div class="tcrm-cc-gauge-card__title">Disk (<t t-esc="state.technical.disk_used"/>/<t t-esc="state.technical.disk_total"/> GB)</div>
                        </div>
                    </div>


                    <div class="tcrm-cc-card">
                        <div class="tcrm-cc-card__header">
                            <span class="material-symbols-outlined">extension</span>
                            TCRM Modules
                        </div>
                        <div class="tcrm-cc-card__body">
                            <t t-if="state.technical.modules and state.technical.modules.length">
                                <div class="tcrm-cc-module-grid">
                                    <t t-foreach="state.technical.modules" t-as="m" t-key="m.id">
                                        <div class="tcrm-cc-module-card">
                                            <div class="tcrm-cc-module-card__name"><t t-esc="m.shortdesc"/></div>
                                            <div class="tcrm-cc-module-card__tech"><t t-esc="m.name"/> v<t t-esc="m.installed_version"/></div>
                                            <span class="tcrm-badge tcrm-badge-success"><t t-esc="m.state"/></span>
                                        </div>
                                    </t>
                                </div>
                            </t>
                        </div>
                    </div>
                </t>
            </div>
        </t>


        <t t-if="state.screen === 'db_console'">
            <div class="tcrm-cc-content">
                <div class="tcrm-cc-db-toolbar">
                    <span class="tcrm-badge tcrm-badge-info">READ-ONLY MODE</span>
                    <span class="tcrm-badge tcrm-badge-muted">SELECT queries only</span>
                </div>

                <div class="tcrm-cc-card tcrm-cc-db-editor">
                    <div class="tcrm-cc-card__header">
                        <span class="material-symbols-outlined">code</span>
                        SQL Query Editor
                        <button class="tcrm-cc-btn tcrm-cc-btn--primary tcrm-cc-btn--sm" style="margin-left: auto;" t-on-click="executeQuery" t-att-disabled="state.sqlLoading">
                            <span class="material-symbols-outlined">play_arrow</span> Execute
                        </button>
                    </div>
                    <div class="tcrm-cc-card__body">
                        <textarea class="tcrm-cc-sql-input" rows="6" t-att-value="state.sqlQuery" t-on-input="onSqlInput" spellcheck="false"/>
                    </div>
                </div>


                <t t-if="state.sqlLoading">
                    <div class="tcrm-cc-loading"><div class="tcrm-cc-spinner"/> Executing…</div>
                </t>
                <t t-if="state.sqlResult">
                    <t t-if="state.sqlResult.error">
                        <div class="tcrm-cc-card" style="border-left: 3px solid #ef4444;">
                            <div class="tcrm-cc-card__body" style="color: #fca5a5;">
                                <strong>Error:</strong> <t t-esc="state.sqlResult.error"/>
                            </div>
                        </div>
                    </t>
                    <t t-elif="state.sqlResult.columns">
                        <div class="tcrm-cc-db-results-bar">
                            <span><t t-esc="state.sqlResult.row_count"/> rows</span>
                            <t t-if="state.sqlResult.truncated">
                                <span class="tcrm-badge tcrm-badge-warning">Truncated to 500</span>
                            </t>
                        </div>
                        <div class="tcrm-cc-card tcrm-cc-db-results">
                            <div class="tcrm-cc-card__body" style="overflow-x: auto;">
                                <table class="tcrm-cc-table tcrm-cc-table--mono">
                                    <thead><tr>
                                        <t t-foreach="state.sqlResult.columns" t-as="col" t-key="col">
                                            <th t-esc="col"/>
                                        </t>
                                    </tr></thead>
                                    <tbody>
                                        <t t-foreach="state.sqlResult.rows" t-as="row" t-key="row_index">
                                            <tr>
                                                <t t-foreach="state.sqlResult.columns" t-as="col" t-key="col">
                                                    <td t-esc="row[col]"/>
                                                </t>
                                            </tr>
                                        </t>
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </t>
                </t>
            </div>
        </t>


        <t t-if="state.screen === 'analytics'">
            <div class="tcrm-cc-content">
                <t t-if="state.analytics">
                    <div class="tcrm-cc-kpi-grid">
                        <div class="tcrm-cc-kpi-card">
                            <div class="tcrm-cc-kpi-card__icon" style="background: #1e40af;">
                                <span class="material-symbols-outlined">apartment</span>
                            </div>
                            <div class="tcrm-cc-kpi-card__body">
                                <div class="tcrm-cc-kpi-card__label">Total Tenants</div>
                                <div class="tcrm-cc-kpi-card__value"><t t-esc="state.analytics.summary.total_tenants"/></div>
                            </div>
                        </div>
                        <div class="tcrm-cc-kpi-card">
                            <div class="tcrm-cc-kpi-card__icon" style="background: #059669;">
                                <span class="material-symbols-outlined">check_circle</span>
                            </div>
                            <div class="tcrm-cc-kpi-card__body">
                                <div class="tcrm-cc-kpi-card__label">Active Tenants</div>
                                <div class="tcrm-cc-kpi-card__value"><t t-esc="state.analytics.summary.active_count"/></div>
                            </div>
                        </div>
                        <div class="tcrm-cc-kpi-card">
                            <div class="tcrm-cc-kpi-card__icon" style="background: #dc2626;">
                                <span class="material-symbols-outlined">warning</span>
                            </div>
                            <div class="tcrm-cc-kpi-card__body">
                                <div class="tcrm-cc-kpi-card__label">At Risk</div>
                                <div class="tcrm-cc-kpi-card__value"><t t-esc="state.analytics.summary.risk_count"/></div>
                            </div>
                        </div>
                        <div class="tcrm-cc-kpi-card">
                            <div class="tcrm-cc-kpi-card__icon" style="background: #7c3aed;">
                                <span class="material-symbols-outlined">speed</span>
                            </div>
                            <div class="tcrm-cc-kpi-card__body">
                                <div class="tcrm-cc-kpi-card__label">System Health</div>
                                <div class="tcrm-cc-kpi-card__value"><t t-esc="fmtPct(state.analytics.summary.system_health)"/></div>
                            </div>
                        </div>
                    </div>

                    <div class="tcrm-cc-toolbar" style="justify-content: flex-end;">
                        <button class="tcrm-cc-btn tcrm-cc-btn--ghost" t-on-click="() =&gt; this.exportAnalytics('csv')">
                            <span class="material-symbols-outlined">download</span> Export CSV
                        </button>
                        <button class="tcrm-cc-btn tcrm-cc-btn--ghost" t-on-click="() =&gt; this.exportAnalytics('excel')">
                            <span class="material-symbols-outlined">download</span> Export Excel
                        </button>
                    </div>

                    <div class="tcrm-cc-card">
                        <div class="tcrm-cc-card__header">
                            <span class="material-symbols-outlined">table_chart</span>
                            Tenant Analytics Report
                        </div>
                        <div class="tcrm-cc-card__body" style="overflow-x: auto;">
                            <table class="tcrm-cc-table">
                                <thead>
                                    <tr>
                                        <th>Tenant ID</th>
                                        <th>Tenant</th>
                                        <th>Growth</th>
                                        <th>Churn Risk</th>
                                        <th>Security</th>
                                        <th>Revenue</th>
                                        <th>MRR</th>
                                        <th>Actions</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <t t-foreach="state.analytics.report_rows || []" t-as="r" t-key="r.tenant_record_id || r.tenant_id">
                                        <tr>
                                            <td class="tcrm-cc-text-mono">
                                                <span contenteditable="true" t-on-input="(ev) =&gt; this.onAnalyticsCellInput(row_index, 'tenant_id', ev)" t-esc="r.tenant_id"/>
                                            </td>
                                            <td>
                                                <a href="#" class="tcrm-cc-link" t-on-click.prevent="() =&gt; this.openTenantDetail(this._tenantIdForOpen(r))">
                                                    <t t-esc="r.tenant_name"/>
                                                </a>
                                            </td>
                                            <td><t t-esc="fmtPct(r.growth_rate || 0)"/></td>
                                            <td><span t-att-class="'tcrm-badge ' + stateBadgeClass(r.churn_risk)" t-esc="r.churn_risk"/></td>
                                            <td><span class="tcrm-badge tcrm-badge-info" t-esc="r.security_status"/></td>
                                            <td><t t-esc="fmtMoney(r.revenue)"/></td>
                                            <td><t t-esc="fmtMoney(r.mrr)"/></td>
                                            <td>
                                                <button class="tcrm-cc-btn tcrm-cc-btn--sm tcrm-cc-btn--ghost" t-on-click="() =&gt; this.openTenantDetail(this._tenantIdForOpen(r))">
                                                    <span class="material-symbols-outlined">visibility</span>
                                                </button>
                                            </td>
                                        </tr>
                                    </t>
                                </tbody>
                            </table>
                        </div>
                    </div>
                </t>
            </div>
        </t>

    </main>


    <t t-if="state.showCreateTenant">
        <div class="tcrm-cc-modal-overlay" t-on-click="closeCreateTenant">
            <div class="tcrm-cc-modal" t-on-click.stop="">
                <div class="tcrm-cc-modal__header">
                    <h3>Create New Tenant</h3>
                    <button class="tcrm-cc-btn tcrm-cc-btn--ghost" t-on-click="closeCreateTenant">
                        <span class="material-symbols-outlined">close</span>
                    </button>
                </div>
                <div class="tcrm-cc-modal__body">
                    <div class="tcrm-cc-form-group">
                        <label>Tenant Name *</label>
                        <input type="text" t-att-value="state.newTenant.name" t-on-input="(ev) =&gt; this.onNewTenantInput('name', ev)" placeholder="e.g. Skyline Developments"/>
                    </div>
                    <div class="tcrm-cc-form-group">
                        <label>Client Name</label>
                        <input type="text" t-att-value="state.newTenant.client_name" t-on-input="(ev) =&gt; this.onNewTenantInput('client_name', ev)" placeholder="Display name"/>
                    </div>
                    <div class="tcrm-cc-form-group">
                        <label>Support Email</label>
                        <input type="email" t-att-value="state.newTenant.support_email" t-on-input="(ev) =&gt; this.onNewTenantInput('support_email', ev)"/>
                    </div>
                    <div class="tcrm-cc-form-group">
                        <label>Support Phone</label>
                        <input type="text" t-att-value="state.newTenant.support_phone" t-on-input="(ev) =&gt; this.onNewTenantInput('support_phone', ev)"/>
                    </div>
                    <div class="tcrm-cc-form-group">
                        <label>Sector</label>
                        <select t-on-change="(ev) =&gt; this.onNewTenantSelect('sector_id', ev)">
                            <option value="">-- Select --</option>
                            <t t-foreach="state.sectors" t-as="s" t-key="s.id">
                                <option t-att-value="s.id" t-esc="s.name"/>
                            </t>
                        </select>
                    </div>
                </div>
                <div class="tcrm-cc-modal__footer">
                    <button class="tcrm-cc-btn tcrm-cc-btn--ghost" t-on-click="closeCreateTenant">Cancel</button>
                    <button class="tcrm-cc-btn tcrm-cc-btn--primary" t-on-click="saveTenant">Create Tenant</button>
                </div>
            </div>
        </div>
    </t>

</div>
</t>
`);
